/** Re-apply the current time to a (possibly cached) schedule: which class is on now, and what is next. */
function restampClock_(sc, ctx) {
  sc.nowMin = ctx.nowMin;
  sc.date = ctx.date;
  sc.simLabel = ctx.simLabel;
  var rows = (sc.dayCol && sc.week[sc.dayCol]) ? sc.week[sc.dayCol].rows : [];
  rows.forEach(function (o) {
    var s = Sched.timeToMin(o.begin), e = Sched.timeToMin(o.end);
    o.current = !!o.meetsToday && s >= 0 && e > s && ctx.nowMin >= s && ctx.nowMin < e;
  });
  var live = rows.filter(function (o) { return o.current; });
  if (live.length > 1) live.forEach(function (o) { o.sharedSlot = true; });
  var nn = Sched.nowAndNext(rows, ctx.nowMin);
  sc.now = nn.now; sc.next = nn.next;
}

/** The expensive assembly. Everything here depends only on the student and the data version, never the clock. */
function buildBootPayload_(who, ctx) {
  var sid = who.studentId;
  var tabs = loadStagingTabs_();

  var classes = Sched.studentClasses(tabs, sid);
  var profile = Sched.studentProfile(tabs, sid, classes);
  var academic = classes.filter(function (c) { return !c.activity; });
  var periodTimes = Sched.buildPeriodTimes(tabs);
  var hasPeriods = academic.some(function (c) { return c.pattern; });
  var elementary = !hasPeriods || /^(K4|K5|K|PK|[1-6])$/i.test(String(profile.grade || '').trim());

  var classList = classListFor_(tabs, sid, classes);
  var byId = {}; classList.forEach(function (c) { byId[c.classId] = c; });

  // Bells (delay / exam days) per weekday of this week — BellHub, cached; FACTS times when unavailable.
  var week = {};
  var dates = weekDates_(ctx.date, ctx.dow);
  var weekBells = bellsForDays_(dates);   // one batched cache read, not five
  for (var d = 1; d <= 5; d++) {
    var bells = weekBells[dates[d - 1]];
    week[String(d)] = { date: dates[d - 1], bellMode: bells.ok ? bells.mode : '', closed: bells.ok && bells.closed && !!(bells.source || bells.mode),
      rows: Sched.annotateSchedule(academic, periodTimes, { dayCol: String(d), nowMin: d === ctx.dow ? ctx.nowMin : -1, quarter: ctx.quarter, bells: bells.slots })
        .map(function (o) { o.color = (byId[o.classId] || {}).color || '#4b5563'; o.short = (byId[o.classId] || {}).short || ''; return o; }) };
  }
  var todayRows = ctx.dayCol ? week[ctx.dayCol].rows : [];
  var nn = Sched.nowAndNext(todayRows, ctx.nowMin);

  // "School day is over" = the end of this student's LAST timed class today (Josh, 2026-09-11); the
  // ROLLOVER_TIME property is the fallback for days with no timed classes. After it, the first Homework tab
  // becomes Tonight (due next school day). Weekends and no-school days are always "rolled".
  var lastEnd = -1;
  todayRows.forEach(function (o) { if (o.meetsToday) { var e = Sched.timeToMin(o.end); if (e > lastEnd) lastEnd = e; } });
  var rollover = { min: lastEnd > 0 ? lastEnd : getRolloverMin_(), source: lastEnd > 0 ? 'lastClass' : 'default' };

  /* The private data holds EVERY student's homework, assignments and scores, so it must never appear in a
     return value — each builder filters to this caller. Only the three tabs Homework needs are loaded:
     `averages` (1,664 rows) is parsed only when the Grades tab is actually opened. */
  // 'grades' is NOT loaded here any more — homeworkPayload_ reads this student's rows from their own cache
  // key (gradesForStudent_), which is what took the whole-school Grades parse out of every build.
  var data = loadDataTabs_(['homework', 'assignments']);
  var hw = homeworkPayload_(who, classList, ctx.date, data);
  return {
    appVersion: APP_VERSION,
    profile: profile, elementary: elementary, classes: classList,
    schedule: { date: ctx.date, dow: ctx.dow, dayCol: ctx.dayCol, nowMin: ctx.nowMin, quarter: ctx.quarter, simLabel: ctx.simLabel,
      week: week, now: nn.now, next: nn.next, dayNames: periodTimes.dayName, rollover: rollover,
      schoolDay: !!ctx.dayCol && !(week[ctx.dayCol] && week[ctx.dayCol].closed) },
    homework: hw,
    // Grades load on demand (gradesApi) — building them here meant every page load parsed the averages table
    // and shipped every assignment in every class to a page that usually never shows them.
    grades: { pending: true },
    timeChoices: TIME_CHOICES, daysBeforeChoices: DAYS_BEFORE_CHOICES,
    /* Sports are fetched separately after first paint (21 calendars is far too slow for a page load). Telling
       the page whether this student is on a team at all means a non-athlete never asks.
       NOTE the feature FLAGS are not here — bootApi stamps them per request. They live in Script Properties
       precisely so the RUN_enable and RUN_disable pairs take effect immediately, and a payload cached for six
       hours would have quietly broken that promise. */
    sports: { onTeam: classList.some(function (c) { return c.activity; }) },
    attendance: {}
  };
}

/** The Grades tab, on demand. Self-only like every endpoint. */
function gradesApi(asId) {
  var t0 = Date.now();
  var who = caller_(asId);
  var classList = classListFor_(loadStagingTabs_(), who.studentId);
  var out = gradesPayload_(who, classList, loadDataTabs_(['assignments', 'averages']));
  perfNote_('grades', Date.now() - t0);
  return out;
}

/**
 * This student's attendance: today, plus every exception day so far this quarter.
 *
 * On demand, never inside the cached boot payload — today's status comes off a tab facts-api-sync rewrites
 * every 5-15 minutes, and a payload cached for hours would freeze it. Self-only like every endpoint.
 *
 * Attendance is EXCEPTION-ONLY at HCS: a day with no row is a day the student was present. So "no record
 * today" is reported as present-so-far rather than as missing data — but only on a day the tab actually
 * loaded, which is why `todayKnown` is separate from `today`.
 */
function attendanceApi(asId) {
  var t0 = Date.now();
  var who = caller_(asId);
  // Re-checked here as well as in doGet: an endpoint must never rely on the client choosing not to call it.
  if (!attendanceEnabled_()) return { disabled: true, connected: false, todayKnown: false, today: null, days: [], counts: {} };
  var sid = String(who.studentId);
  var todayIso = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');

  var pick = function (r) {
    return { date: String(r['Date'] || '').slice(0, 10), code: String(r['Code'] || ''), status: String(r['Status'] || ''),
      detail: String(r['Detail'] || ''), excused: String(r['Excused'] || '') };
  };

  // TODAY — from staging, refreshed all day. null tab = we could not check, which is NOT "present".
  var liveRows = loadAttendanceToday_();
  var todayKnown = liveRows !== null;
  var today = null;
  if (todayKnown) {
    var mine = liveRows.filter(function (r) { return String(r['Student ID']) === sid && String(r['Date'] || '').slice(0, 10) === todayIso; });
    if (mine.length) today = pick(mine[0]);
  }

  // THIS QUARTER — from the private Sheet. Today is dropped from the history so the live row above is the
  // single source for today and the two can never disagree on screen.
  var data = loadDataTabs_(['attendance']);
  var hist = ((data && data.attendance) || []).filter(function (r) {
    return String(r['Student ID']) === sid && String(r['Date'] || '').slice(0, 10) < todayIso;
  }).map(pick);
  hist.sort(function (a, b) { return a.date < b.date ? 1 : a.date > b.date ? -1 : 0; });   // newest first

  var all = hist.concat(today ? [today] : []);
  var counts = { absent: 0, late: 0, leftEarly: 0, excused: 0, unexcused: 0 };
  all.forEach(function (d) {
    if (d.status === 'Absent') counts.absent++;
    else if (d.status === 'Late') counts.late++;
    else if (d.status === 'Left early') counts.leftEarly++;
    if (d.excused === 'Y') counts.excused++; else if (d.excused === 'N') counts.unexcused++;
  });

  perfNote_('attendance', Date.now() - t0);
  return {
    connected: !!data, todayKnown: todayKnown, today: today, todayIso: todayIso,
    days: hist, counts: counts, quarter: Sched.quarterForDate(Sched.parseQuarterRanges(getQuarterDatesRaw_()), todayIso),
    lastSyncAt: (data && data.meta && data.meta.lastSyncAt) || ''
  };
}

/* ---------------------------------------------------------------- homework ---- */

/** One student's classes with colour, short name, teacher email and support flag — shared by boot, homework, notify. */
function classListFor_(tabs, sid, classes) {
  classes = classes || Sched.studentClasses(tabs, sid);
  var colors = Sched.assignColors(classes);
  var emails = Sched.teacherEmails(tabs, classes.map(function (c) { return c.teacher; }));
  return classes.map(function (c) {
    return { classId: c.classId, code: c.code, name: c.description, teacher: c.teacher, teacherEmail: emails[c.teacher] || '', room: c.room, period: c.period,
      quarters: c.quarters, activity: c.activity, support: isSupportClass_(c), dept: c.dept, category: c.category,
      color: colors[String(c.classId)] || '#4b5563', short: Sched.shortName(c.description) };
  });
}

/** Homeroom, study hall, lunch, chapel: they appear on the schedule but never carry homework or grades (Josh, 2026-09-11). */
function isSupportClass_(c) {
  return Sched.isHomeroomClass(c) || /\b(study hall|lunch|chapel|advisory|homeroom)\b/i.test(String(c.description || '') + ' ' + String(c.code || ''));
}

function homeworkPayload_(who, classList, todayIso, data) {
  data = data || loadDataTabs_();
  if (!data) return { connected: false, items: [], meta: {} };
  var today0 = todayIso || Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  /* No-school days so "next class day" skips them. The list is computed once a day by the sync and stored in
     Meta — asking BellHub here would mean up to ~45 cross-library calls inside a student's page load. The
     manually-set NO_SCHOOL_DATES property is always merged in, so a date Josh adds takes effect immediately. */
  var noSchoolMap = {};
  String((data.meta && data.meta.noSchoolDays) || '').split(',').forEach(function (d) { if (d) noSchoolMap[d] = 'bells'; });
  var manual = noSchoolFromProperty_();
  Object.keys(manual).forEach(function (d) { noSchoolMap[d] = manual[d]; });
  var noSchool = Object.keys(noSchoolMap);
  var idSet = {};
  classList.forEach(function (c) { if (!c.support) idSet[String(c.classId)] = true; });
  var hwRows = data.homework.filter(function (r) { return idSet[String(r['Class ID'])]; })
    .map(function (r) { return { classId: r['Class ID'], planDate: r['Plan Date'], homework: r['Homework'], homeworkHTML: r['Homework HTML'] }; });
  var asRows = data.assignments.filter(function (r) { return idSet[String(r['Class ID'])]; })
    .map(function (r) { return { id: r['Assignment ID'], classId: r['Class ID'], title: r['Title'], description: r['Description'],
      dateAssigned: r['Date Assigned'], dateDue: r['Date Due'], maxPoints: r['Max Points'] === '' ? null : Number(r['Max Points']) }; });
  var items = Due.buildItems(hwRows, asRows, { noSchool: noSchool });
  var byId = {}; classList.forEach(function (c) { byId[c.classId] = c; });
  /* This student's rows only, from their own cache key — see gradesForStudent_. Scanning the whole school's
     Grades table here was ~550 ms of every build, and it grows every day. */
  var myGrades = {};
  gradesForStudent_(who.studentId).forEach(function (g) { myGrades[g['Assignment ID']] = g; });
  var today = today0;
  var from = Due.addDays(today, -10), to = Due.addDays(today, 28);
  var out = items.filter(function (it) { return it.dueOn >= from && it.dueOn <= to; }).map(function (it) {
    var c = byId[it.classId] || {};
    var g = it.assignmentId ? myGrades[it.assignmentId] : null;
    return { key: it.key, classId: it.classId, className: c.name || '', short: c.short || '', color: c.color || '#4b5563', teacher: c.teacher || '',
      source: it.source, title: it.title, detail: it.detail, assignedOn: it.assignedOn, lastSeenOn: it.lastSeenOn, dueOn: it.dueOn,
      dueSource: it.dueSource, anchor: it.anchor, points: it.points, timesTyped: it.timesTyped,
      grade: g ? { display: g['Display Grade'], status: g['Status'], earned: g['Earned'], max: g['Max'] } : null };
  });
  // NOTE: `data` is deliberately NOT returned. It is the whole school's gradebook; returning it once shipped
  // every student's scores to every student's browser. Callers that need it pass it in.
  // Only the two Meta fields the page shows. The whole tab carried lastError (up to 200 chars of a FACTS error
  // body), request counts and ids to every student (release review 2026-10-08).
  var m = data.meta || {};
  return { connected: true, items: out, today: today, meta: { lastSyncAt: m.lastSyncAt || '', lastSyncOk: m.lastSyncOk || '' }, noSchool: noSchoolMap };
}

/**
 * Which GbkSummary row is the CLASS average rather than a category sub-average (Homework, Tests, …)?
 * Deliberately conservative: a row with no category (or category 0) is the overall; a single row for the class
 * is the overall; anything else is ambiguous and shows NO average rather than a wrong one.
 * @return {?{row:Object, average:string, letter:string, why:string}}
 */
function pickOverallAverage_(rows) {
  if (!rows || !rows.length) return null;
  var val = function (r, why) {
    var a = String(r['Average'] || '').trim();
    if (!a && r['Points Possible'] && Number(r['Points Possible']) > 0) a = String(Math.round((Number(r['Points Earned']) / Number(r['Points Possible'])) * 1000) / 10);
    if (!a) return null;
    return { row: r, average: a, letter: String(r['Letter'] || '').trim(), why: why };
  };
  // Proved against live data 2026-09-11: FACTS writes the CLASS total as category -1, and it is the only row
  // carrying a letter grade; categories 1..n are the per-category sub-averages (Homework, Tests, …).
  var cat = function (r) { return String(r['Category ID'] == null ? '' : r['Category ID']).trim(); };
  var overall = rows.filter(function (r) { return cat(r) === '-1'; });
  if (overall.length === 1) return val(overall[0], 'category -1, the class total');
  var lettered = rows.filter(function (r) { return String(r['Letter'] || '').trim(); });
  if (lettered.length === 1) return val(lettered[0], 'the only row with a letter grade');
  var noCat = rows.filter(function (r) { return cat(r) === '' || cat(r) === '0'; });
  if (noCat.length === 1) return val(noCat[0], 'the row with no category');
  if (rows.length === 1) return val(rows[0], 'the only row for this class');
  return null;
}

/** Per class: every assignment this year with the caller's score, plus the class average when enabled + unambiguous. */
function gradesPayload_(who, classList, data) {
  if (!data) return { connected: false, classes: [] };
  var mine = {};
  gradesForStudent_(who.studentId).forEach(function (g) { mine[g['Assignment ID']] = g; });
  // Second gate (the first is in bootApi): averages never leave the server until Josh has verified them.
  var showAvg = averagesEnabled_();
  var avgByClass = {};
  if (showAvg) {
    (data.averages || []).forEach(function (r) {
      if (String(r['Student ID']) !== String(who.studentId)) return;
      (avgByClass[String(r['Class ID'])] = avgByClass[String(r['Class ID'])] || []).push(r);
    });
  }
  var out = classList.filter(function (c) { return !c.activity && !c.support; }).map(function (c) {
    var rows = data.assignments.filter(function (a) { return String(a['Class ID']) === String(c.classId); }).map(function (a) {
      var g = mine[a['Assignment ID']];
      return { id: a['Assignment ID'], title: a['Title'] || a['Description'] || 'Assignment', description: a['Description'], dateDue: a['Date Due'], dateAssigned: a['Date Assigned'],
        maxPoints: a['Max Points'], display: g ? g['Display Grade'] : '', status: g ? g['Status'] : '', earned: g ? g['Earned'] : '', max: g ? (g['Max'] || a['Max Points']) : a['Max Points'] };
    }).sort(function (a, b) { return a.dateDue < b.dateDue ? 1 : a.dateDue > b.dateDue ? -1 : 0; });
    var graded = rows.filter(function (r) { return r.earned !== '' || r.display !== ''; }).length;
    var pick = showAvg ? pickOverallAverage_(avgByClass[String(c.classId)]) : null;
    return { classId: c.classId, name: c.name, short: c.short, color: c.color, teacher: c.teacher, assignments: rows, graded: graded, total: rows.length,
      average: pick ? pick.average : '', letter: pick ? pick.letter : '' };
  });
  return { connected: true, classes: out, averagesOn: showAvg };
}

/** Lightweight refresh of the due list only. */
function homeworkApi(asId) {
  var who = caller_(asId);
  return homeworkPayload_(who, classListFor_(loadStagingTabs_(), who.studentId));
}

/* ---------------------------------------------------------------- diagnostics (editor Run menu) ---- */

/** Ground-truth dump for one student (GATE0_TEST_EMAIL's facts_id, or a hardcoded id below): tabs, classes, join, items. */
/**
 * The whole week's schedule, built the way a student's page builds it — in Code.gs, editor Run menu.
 *
 * Uses buildBootPayload_ itself rather than re-deriving the schedule, so this confirms what the APP produces,
 * not what a parallel copy of the logic would. That distinction is the point: a diagnostic that reimplements
 * the thing it checks can pass while the app is broken.
 *
 * Run it on a weekend and `dayCol` is empty and "today" is blank — that is correct, not a fault. The Mon-Fri
 * grid below is the part that proves the schedule is intact.
 */
function RUN_checkSchedule() {
  requireOperator_();
  var email = String(props_().getProperty(PROP_GATE0_TEST_EMAIL) || '').toLowerCase();
  var sid = email ? directoryLookup_(email).factsId : '';
  if (!sid) { Logger.log('Set GATE0_TEST_EMAIL first.'); return; }
  var ctx = schedCtx_('');
  var who = { studentId: sid, email: email, fullName: '', isAdmin: false, viewingAs: '' };
  var p = buildBootPayload_(who, ctx);
  var sc = p.schedule;

  Logger.log('%s (%s) — %s, quarter %s', email, sid, ctx.date, ctx.quarter);
  Logger.log('elementary=%s (no period patterns) · classes=%s', p.elementary, (p.classes || []).length);
  if (!ctx.dayCol) Logger.log('Today is a WEEKEND — an empty "today" is correct. The week grid below is the real check.');
  Logger.log('rollover: %s (%s)', sc.rollover.min, sc.rollover.source);
  Logger.log('%s', new Array(78).join('-'));

  var names = sc.dayNames || {};
  var problems = [];

  /* This check said "intact" while the Schedule tab was showing a week that had already finished, so it now
     asserts WHICH week it got. On a weekday the grid must contain today; on a weekend it must be the week
     ahead, never the one just ended. */
  var mon = sc.week['1'] && sc.week['1'].date, fri = sc.week['5'] && sc.week['5'].date;
  Logger.log('week shown: %s .. %s', mon, fri);
  if (ctx.dayCol) {
    if (!(mon <= ctx.date && ctx.date <= fri)) problems.push('today (' + ctx.date + ') is not inside the week shown');
  } else if (mon <= ctx.date) {
    problems.push('weekend, but the week shown (' + mon + ') is not the week AHEAD — a student would see a finished week');
  }

  ['1', '2', '3', '4', '5'].forEach(function (d) {
    var day = sc.week[d];
    if (!day) { problems.push('day ' + d + ' MISSING from the week'); return; }
    var meets = (day.rows || []).filter(function (r) { return r.meetsToday; });
    // FACTS keeps a full timetable for a closed day. That is fine in the data and wrong on screen.
    if (day.closed && meets.length) Logger.log('    (%s classes are listed for this closed day; the page hides them)', meets.length);
    Logger.log('%s %s  bells=%s%s  — %s class(es) meet', (names[d] || ('day ' + d)), day.date,
      day.bellMode || 'normal', day.closed ? ' CLOSED' : '', meets.length);
    meets.forEach(function (r) {
      Logger.log('    %s  %s  %s-%s  %s%s', (String(r.periodShort || '-') + '    ').slice(0, 5),
        String(r.description || '').slice(0, 34), r.beginShort || '?', r.endShort || '?',
        r.room ? 'Rm ' + r.room : '', r.current ? '  <- NOW' : '');
      if (!r.beginShort || !r.endShort) problems.push(day.date + ' ' + r.description + ' has no clock time');
    });
    if (!meets.length && !day.closed) problems.push(day.date + ' has NO classes and is not marked closed');
  });

  Logger.log('%s', new Array(78).join('-'));
  Logger.log('now=%s  next=%s', sc.now ? (sc.now.description + ' ' + sc.now.beginShort) : '(none)',
    sc.next ? (sc.next.description + ' ' + sc.next.beginShort) : '(none)');
  Logger.log('homework items in window: %s · grades pending=%s · sports onTeam=%s',
    (p.homework.items || []).length, !!(p.grades && p.grades.pending), !!(p.sports && p.sports.onTeam));
  if (problems.length) { Logger.log('!! PROBLEMS:'); problems.forEach(function (x) { Logger.log('   %s', x); }); }
  else Logger.log('Schedule looks intact: every weekday has classes with clock times.');
}

function RUN_diagnoseStudent() {
  requireOperator_();
  var email = String(props_().getProperty(PROP_GATE0_TEST_EMAIL) || '').toLowerCase();
  var d = directoryLookup_(email);
  var sid = d.factsId;
  Logger.log('email=%s facts_id=%s ou=%s err=%s', email, sid || '(none)', d.ou, d.error || '-');
  if (!sid) return;
  var tabs = loadStagingTabs_();
  Logger.log('staging tabs: %s', tabs.map(function (t) { return t.name + '(' + t.values.length + ')'; }).join(', '));
  var classes = Sched.studentClasses(tabs, sid);
  Logger.log('classes (%s): %s', classes.length, classes.map(function (c) { return c.classId + ' ' + c.description + ' [' + c.period + '/' + c.pattern + ']'; }).join(' | '));
  var profile = Sched.studentProfile(tabs, sid, classes);
  Logger.log('profile: %s', JSON.stringify(profile));
  var ctx = schedCtx_('');
  var rows = Sched.annotateSchedule(classes.filter(function (c) { return !c.activity; }), Sched.buildPeriodTimes(tabs), { dayCol: ctx.dayCol, nowMin: ctx.nowMin, quarter: ctx.quarter });
  Logger.log('today %s dayCol=%s nowMin=%s q=%s', ctx.date, ctx.dayCol, ctx.nowMin, ctx.quarter);
  rows.forEach(function (o) { Logger.log('  %s %s %s-%s %s%s', o.periodShort, o.description, o.beginShort, o.endShort, o.meetsToday ? '' : '(off)', o.current ? ' NOW' : ''); });
  var data = loadDataTabs_(['homework', 'assignments', 'grades', 'averages']);
  if (!data) { Logger.log('data sheet: not set up (Phase 2 pending)'); return; }
  Logger.log('data: homework=%s assignments=%s grades=%s meta=%s', data.homework.length, data.assignments.length, data.grades.length, JSON.stringify(data.meta));
  var hw = homeworkPayload_({ email: email, studentId: sid }, classListFor_(tabs, sid, classes));
  Logger.log('items in window: %s', hw.items.length);
  hw.items.slice(0, 40).forEach(function (it) { Logger.log('  %s [%s] %s — %s', it.dueOn, it.dueSource, it.short, it.title.slice(0, 80)); });
}

/** Gate 0 self-check from the editor as itscripts@ — proves the manifest + AdminDirectory scope are live. */
function RUN_gate0Self() {
  requireOperator_();
  var me = Session.getEffectiveUser().getEmail();
  var d = directoryLookup_(me);
  Logger.log('%s %s', APP_NAME, APP_VERSION);
  Logger.log('effective user=%s  ou=%s  error=%s', me, d.ou || '(none)', d.error || '(none)');
  Logger.log('AdminDirectory reachable: %s', d.error ? 'NO — accept the OAuth prompt, then re-run' : 'yes');
}

/* ===== Sports.gs ===== */
/**
 * Sports.gs — the student's games: when they get out of class, when the bus leaves, where it is.
 *
 * WHERE THE DATA COMES FROM
 * Two halves that meet nowhere else. FACTS knows a student is ON a team (an Activity=Y class enrolment
 * such as "JVBSoc"). The 21 team Google Calendars know when the games are — and the dismissal exists
 * only as prose a coach typed into an event description. Athletics.js joins them.
 *
 * HOW IT READS
 * PUBLIC .ics over plain HTTPS, exactly as sports-calendar/tools/bake.mjs does: no Calendar scope, no
 * sharing change, and nothing here can write to a calendar. All 21 fetched in ONE parallel fetchAll,
 * parsed for a three-week window in that single pass, and cached script-wide — so the first student to
 * open the tab pays for everyone.
 *
 * NOT IN THE BOOT PAYLOAD. The fetch is far too slow to sit in a page load, so the client asks for it
 * after first paint. A student with no teams never triggers a single request.
 *
 * FAILURE POSTURE: every path degrades to "no games listed", never to a guessed time. A failed sweep is
 * NOT cached as "nothing on" — Google rate-limits these URLs, and a 429 looks identical on screen to a
 * quiet week. `ok:false` lets the page say "couldn't check" instead of "nothing".
 */

var ATHLETICS_CACHE_SECS = 1800;          // 30 min: coaches edit dismissals the morning of a game
var ATHLETICS_PARTIAL_CACHE_SECS = 300;   // some calendars 429'd — retry sooner, don't lock in a gap
var ATHLETICS_ICS_URL = 'https://calendar.google.com/calendar/ical/%ID%/public/basic.ics';
var ATHLETICS_DAYS_AHEAD = 21;

/** Every team event in [from, to], across every calendar. One fetchAll, cached. */
function athleticsRangeCached_(fromIso, toIso) {
  var cache = CacheService.getScriptCache();
  var key = 'ath_' + APP_VERSION + '_' + fromIso + '_' + toIso;
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);

  // `teamsFailed` carries a human reason ("soccer-jv-boys (HTTP 429)"); `failedIds` is the bare id list, so a
  // caller can ask "did THIS student's team fail?" without string-matching a log message.
  var payload = { from: fromIso, to: toIso, events: [], ok: true, teamsFailed: [], failedIds: [] };
  try {
    var requests = ATHLETICS_TEAMS.map(function (t) {
      return { url: ATHLETICS_ICS_URL.replace('%ID%', encodeURIComponent(t.calendarId)), muteHttpExceptions: true, followRedirects: true };
    });
    var responses = UrlFetchApp.fetchAll(requests);
    responses.forEach(function (res, i) {
      var team = ATHLETICS_TEAMS[i];
      try {
        if (res.getResponseCode() !== 200) {
          payload.teamsFailed.push(team.id + ' (HTTP ' + res.getResponseCode() + ')');
          payload.failedIds.push(team.id);
          return;
        }
        Ath.parseIcs(res.getContentText(), team.id, fromIso, toIso).forEach(function (ev) { payload.events.push(ev); });
      } catch (inner) {
        payload.teamsFailed.push(team.id + ' (' + String(inner).slice(0, 60) + ')');
        payload.failedIds.push(team.id);
      }
    });
  } catch (e) {
    Logger.log('Athletics calendars unavailable: %s', e);
    payload.ok = false;
    payload.error = String(e).slice(0, 200);
    return payload; // never cached
  }

  if (payload.teamsFailed.length === ATHLETICS_TEAMS.length) {
    payload.ok = false;
    Logger.log('Athletics: ALL %s calendars failed (%s) — not caching, will retry.', ATHLETICS_TEAMS.length, payload.teamsFailed.slice(0, 3).join('; '));
    return payload;
  }
  if (payload.teamsFailed.length) {
    Logger.log('Athletics: %s of %s calendars failed: %s', payload.teamsFailed.length, ATHLETICS_TEAMS.length, payload.teamsFailed.join('; '));
    cachePutChunked_(cache, key, JSON.stringify(payload), ATHLETICS_PARTIAL_CACHE_SECS);
    return payload;
  }
  cachePutChunked_(cache, key, JSON.stringify(payload), ATHLETICS_CACHE_SECS);
  return payload;
}

/** The team table without the calendar ids, which are of no use to a browser. */
function athleticsPublicTeams_() {
  return ATHLETICS_TEAMS.filter(function (t) { return !t.hidden; })
    .map(function (t) { return { id: t.id, sport: t.sport, gender: t.gender, level: t.level }; });
}

/** One student's activity classes + gender → their games. Shared by the endpoint and the diagnostics. */
function athleticsForStudentId_(tabs, studentId, fromIso, toIso) {
  var classes = Sched.studentClasses(tabs, studentId);
  var activities = classes.filter(function (c) { return c.activity; });
  var profile = Sched.studentProfile(tabs, studentId, classes);
  if (!activities.length) return { enrolled: false, teams: [], events: [], ok: true };
  var range = athleticsRangeCached_(fromIso, toIso);
  var joined = Ath.forStudent(activities, profile.gender, ATHLETICS_TEAMS, range.events, fromIso, toIso);

  /* Did THIS student's own calendar fail?
     A partial sweep keeps ok:true, because 20 of 21 teams did fine. But for the one student whose team was
     the failure, "0 events, ok:true" renders as "nothing scheduled in the next three weeks" — a confident
     statement that their season is empty, built on a 429. This project's rule is that a failed sweep is never
     shown as "no games", and until now that only held when ALL 21 calendars failed at once.
     Found 2026-09-27: NJM's soccer games vanished this way. */
  var failedIds = range.failedIds || [];
  var mineFailed = (joined.teams || []).filter(function (t) { return failedIds.indexOf(t.id) !== -1; });
  if (mineFailed.length) {
    Logger.log('Athletics: %s of this student\'s own calendars failed (%s) — reporting "could not check", not "no games".',
      mineFailed.length, mineFailed.map(function (t) { return t.id; }).join(', '));
  }
  return {
    enrolled: true, teams: joined.teams, events: joined.events,
    ok: range.ok && !mineFailed.length,
    partial: (range.teamsFailed || []).length > 0,
    myTeamsFailed: mineFailed.map(function (t) { return t.name; }),
    activities: activities.map(function (a) { return { code: a.code, name: a.description || a.code }; })
  };
}

/**
 * Client endpoint, called after first paint. Self-only like every endpoint here, and gated server-side
 * as well as in the page — an endpoint must never depend on the client choosing not to call it.
 */
function athleticsApi(asId) {
  var t0 = Date.now();
  var who = caller_(asId);
  if (!athleticsEnabled_()) return { disabled: true, enrolled: false, teams: [], events: [], ok: true };
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');

  /* The calendar sweep behind this is already shared script-wide, but the JOIN still had to parse the whole
     school's schedule tab to find this student's teams — on every open of the app. Cache the finished card
     per student. A failed or partial sweep is deliberately NOT cached (same rule as the sweep itself): a
     429 must never harden into "no games this week". */
  var cache = CacheService.getScriptCache();
  var key = 'athstu_' + APP_VERSION + '_' + who.studentId + '_' + today + '_' + stagingVersion_();
  var hit = cacheGetChunked_(cache, key);
  if (hit) { perfNote_('sports-cached', Date.now() - t0); return JSON.parse(hit); }

  var out = athleticsForStudentId_(loadStagingTabs_(), who.studentId, today, Due.addDays(today, ATHLETICS_DAYS_AHEAD));
  /* Cache on `ok`, which now means "this student's own calendars were all readable" — not on `partial`, which
     is true whenever ANY of the 21 failed. A failure on some other team's calendar says nothing about the
     correctness of this student's result, and refusing to cache it just made every request redo the join. */
  if (out.ok) cachePutChunked_(cache, key, JSON.stringify(out), ATHLETICS_CACHE_SECS);
  perfNote_('sports-built', Date.now() - t0);
  return out;
}

/* ---------------------------------------------------------------- diagnostics (editor Run menu) ---- */

/**
 * What the GATE0_TEST_EMAIL student would actually see. Run this BEFORE RUN_enableAthletics —
 * it is the only way to tell "this student has no games" from "the matcher missed their team".
 */
function RUN_athleticsCheck() {
  requireOperator_();
  var email = String(props_().getProperty(PROP_GATE0_TEST_EMAIL) || '').toLowerCase();
  var sid = email ? directoryLookup_(email).factsId : '';
  if (!sid) { Logger.log('Set GATE0_TEST_EMAIL to a student email first.'); return; }
  var tabs = loadStagingTabs_();
  var classes = Sched.studentClasses(tabs, sid);
  var profile = Sched.studentProfile(tabs, sid, classes);
  var activities = classes.filter(function (c) { return c.activity; });
  Logger.log('%s (%s) gender=%s — %s activity class(es)', email, sid, profile.gender || '(blank)', activities.length);
  activities.forEach(function (a) {
    var teams = Ath.matchTeams(a, profile.gender, ATHLETICS_TEAMS);
    Logger.log('   %s "%s" -> %s', a.code, a.description || '(blank description)',
      teams.length ? teams.map(function (t) { return t.id; }).join(', ') : '(NO TEAM — matcher missed it, or it is a club/bus route)');
  });
  if (!activities.length) { Logger.log('   No Activity=Y classes. Either not on a team, or the course\'s activity flag is off in FACTS.'); return; }
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var res = athleticsForStudentId_(tabs, sid, today, Due.addDays(today, ATHLETICS_DAYS_AHEAD));
  Logger.log('--- %s game(s) in the next %s days (calendars ok=%s%s)', res.events.length, ATHLETICS_DAYS_AHEAD, res.ok, res.partial ? ', SOME CALENDARS FAILED' : '');
  res.events.forEach(function (ev) {
    Logger.log('   %s %s | %s | %s | start %s | dismiss %s | depart %s', ev.date, ev.team, ev.title || '(untitled)',
      ev.location || '(no location)', ev.startLabel || (ev.allDay ? 'all day' : '-'), ev.dismissLabel || '(not posted)', ev.departLabel || '(not posted)');
  });
  if (!res.events.length) Logger.log('   (nothing on their calendars in that window)');
  if (res.myTeamsFailed && res.myTeamsFailed.length) Logger.log('   !! THIS STUDENT\'S OWN calendars failed: %s', res.myTeamsFailed.join(', '));

  /* The line above is FRESH. What a student actually sees comes out of the per-student cache, and the two can
     disagree — a cache written during a bad sweep outlives the sweep. Comparing them is the difference
     between "the engine works" and "the app is right", which is the distinction that matters when someone
     reports games missing. */
  var cache = CacheService.getScriptCache();
  var key = 'athstu_' + APP_VERSION + '_' + sid + '_' + today + '_' + stagingVersion_();
  var cached = cacheGetChunked_(cache, key);
  Logger.log('--- what the APP would serve (per-student cache) ---');
  if (!cached) {
    Logger.log('   nothing cached — the next open rebuilds, so it would match the fresh result above.');
  } else {
    var c = JSON.parse(cached);
    Logger.log('   cached: %s game(s), ok=%s%s', (c.events || []).length, c.ok,
      (c.myTeamsFailed && c.myTeamsFailed.length) ? ', own calendars failed: ' + c.myTeamsFailed.join(', ') : '');
    if ((c.events || []).length !== res.events.length) {
      Logger.log('   !! MISMATCH — the cache is stale or was written during a failed sweep.');
      Logger.log('      Run RUN_athleticsRefresh (Sports.gs) to drop it, then re-run this.');
    }
  }
  Logger.log('Athletics is currently %s for students.', athleticsEnabled_() ? 'ON' : 'OFF — run RUN_enableAthletics (Config.gs) once this looks right');
}

/**
 * Drop every athletics cache so the next request re-fetches — in Sports.gs, editor Run menu.
 *
 * For the case where a rate-limited sweep got cached and students are seeing fewer games than exist. Safe to
 * run any time; the only cost is one calendar sweep on the next open.
 */
function RUN_athleticsRefresh() {
  requireOperator_();
  var cache = CacheService.getScriptCache();
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var to = Due.addDays(today, ATHLETICS_DAYS_AHEAD);
  cacheDropChunked_(cache, 'ath_' + APP_VERSION + '_' + today + '_' + to);
  // Per-student entries cannot be enumerated; the salt in the boot key does not cover them, so drop the
  // sweep and let each student's 30-minute entry lapse. Bumping ATHLETICS_CACHE_SECS is not needed for that.
  Logger.log('Dropped the shared calendar sweep for %s..%s.', today, to);
  Logger.log('Per-student entries expire within %s minutes on their own.', Math.round(ATHLETICS_CACHE_SECS / 60));
  var fresh = athleticsRangeCached_(today, to);
  Logger.log('Re-swept: %s event(s), ok=%s, %s calendar(s) failed%s', (fresh.events || []).length, fresh.ok,
    (fresh.failedIds || []).length, (fresh.teamsFailed || []).length ? ' — ' + fresh.teamsFailed.join('; ') : '');
}

/** Raw calendar dump for one date — traces a wrong dismissal to the coach's text. Edit DATE. */
function RUN_athleticsTest() {
  requireOperator_();
  var DATE = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd'); // <- edit me
  var payload = athleticsRangeCached_(DATE, DATE);
  Logger.log('=== %s — %s event(s), ok=%s', DATE, payload.events.length, payload.ok);
  if (payload.error) Logger.log('batch error: %s', payload.error);
  if ((payload.teamsFailed || []).length) Logger.log('calendars that failed: %s', payload.teamsFailed.join(', '));
  payload.events.forEach(function (ev) {
    Logger.log('  %s | %s | start=%s | DISMISS=%s DEPART=%s | %s', ev.teamId, ev.title || '(untitled)',
      ev.start || 'all-day', ev.dismiss || '(not posted)', ev.depart || '(not posted)', ev.location || '');
  });
  if (!payload.events.length) Logger.log('  (no team has an event on this date)');
}

/**
 * Every distinct Activity=Y class in the export and the calendars it resolves to. Anything printed as
 * "(no team)" is either a club or bus route (expected) or a sport the matcher is missing.
 */
function RUN_athleticsMatchTest() {
  requireOperator_();
  var tabs = loadStagingTabs_();
  var sched = Sched.tabByName(tabs, ['Student Schedules']);
  if (!sched) { Logger.log('No Student Schedules tab.'); return; }
  var h = Sched.headerMap(sched.values[0]);
  var seen = {};
  for (var r = 1; r < sched.values.length; r++) {
    var row = sched.values[r];
    var cell = function (n) { return h[n] === undefined ? '' : Sched.cellToString(row[h[n]]).trim(); };
    if (cell('Activity') !== 'Y') continue;
    var code = cell('Class Code'), desc = cell('Class Description');
    var k = code + '|' + desc;
    if (!seen[k]) seen[k] = { code: code, desc: desc, dept: cell('Course Dept'), n: 0 };
    seen[k].n++;
  }
  var keys = Object.keys(seen).sort();
  Logger.log('=== %s distinct Activity=Y classes ===', keys.length);
  var unmatched = 0;
  keys.forEach(function (k) {
    var a = seen[k];
    var fmt = function (list) { return list.length ? list.map(function (t) { return t.id; }).join(', ') : '(no team)'; };
    var boys = Ath.matchTeams({ code: a.code, description: a.desc }, 'M', ATHLETICS_TEAMS);
    var girls = Ath.matchTeams({ code: a.code, description: a.desc }, 'F', ATHLETICS_TEAMS);
    if (!boys.length && !girls.length) unmatched++;
    Logger.log('  %s "%s" [%s, %s students]  M -> %s   F -> %s', a.code, a.desc || '(blank)', a.dept || 'no dept', a.n, fmt(boys), fmt(girls));
  });
  Logger.log('=== %s of %s resolved to no calendar (clubs and bus routes are expected here) ===', unmatched, keys.length);
}

/* ===== Notify.gs ===== */
/**
 * Notify.gs — email notifications, per student, OFF until the student turns something on (Josh, 2026-09-11).
 *
 * Types (each independently switchable in More → Notifications):
 *   daily    — "what's due tonight" at a time the student picks (school days only by default)
 *   weekly   — the week ahead, on a weekday + time the student picks
 *   changes  — a teacher posted or edited homework / an assignment, within one sync cycle, for chosen classes
 *   tests    — a test or quiz is N days away
 *
 * Everything is sent by MailApp from itscripts@ to the student's OWN school address only. Every email is also
 * written to the Notices tab, which is what the in-app Inbox (More → Inbox) shows. Preferences live in the
 * Prefs tab keyed by email. The 30-minute sync run drives all sending (notifyAfterSync_), so nothing here
 * needs its own trigger. MailApp quota is ~1,500/day: change alerts are capped per student per day.
 */

var PREFS_TAB = 'Prefs';
var NOTICES_TAB = 'Notices';
var NOTICES_KEEP_PER_STUDENT = 40;
var CHANGE_ALERTS_PER_DAY = 6;
var TEST_RE_SERVER = /\b(test|quiz|quizzes|exam|midterm|final|assessment)\b|\bT\s?chp|\bQ\d|\bQ\s?chp/i;
var TIME_CHOICES = ['15:30', '16:00', '17:00', '18:00', '19:00', '20:00', '21:00'];
var DAYS_BEFORE_CHOICES = [1, 2, 3, 5, 7];

function defaultPrefs_() {
  return { daily: { on: false, time: '18:00', schoolDaysOnly: true }, weekly: { on: false, day: 0, time: '18:00' },
    changes: { on: false, classes: [] }, tests: { on: false, daysBefore: 2 }, lastDaily: '', lastWeekly: '', updated: '' };
}

/** Validate + normalise a prefs object from the client. `classIds` = the student's own class ids. */
function cleanPrefs_(raw, classIds, prev) {
  var p = defaultPrefs_();
  raw = raw || {};
  var timeOk = function (t) { return TIME_CHOICES.indexOf(String(t)) !== -1 ? String(t) : '18:00'; };
  if (raw.daily) { p.daily.on = !!raw.daily.on; p.daily.time = timeOk(raw.daily.time); p.daily.schoolDaysOnly = raw.daily.schoolDaysOnly !== false; }
  if (raw.weekly) { p.weekly.on = !!raw.weekly.on; p.weekly.time = timeOk(raw.weekly.time); var d = Number(raw.weekly.day); p.weekly.day = (d >= 0 && d <= 6) ? d : 0; }
  if (raw.changes) { p.changes.on = !!raw.changes.on; p.changes.classes = (raw.changes.classes || []).map(String).filter(function (id) { return classIds.indexOf(id) !== -1; }); }
  if (raw.tests) { p.tests.on = !!raw.tests.on; var n = Number(raw.tests.daysBefore); p.tests.daysBefore = DAYS_BEFORE_CHOICES.indexOf(n) !== -1 ? n : 2; }
  if (prev) { p.lastDaily = prev.lastDaily || ''; p.lastWeekly = prev.lastWeekly || ''; }
  p.updated = Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd'T'HH:mm:ss");
  return p;
}

/* ---------------------------------------------------------------- storage ---- */

function prefsSheet_(ss) {
  var sh = ss.getSheetByName(PREFS_TAB);
  if (!sh) { sh = ss.insertSheet(PREFS_TAB); sh.appendRow(['Email', 'Student ID', 'Prefs JSON', 'Updated']); }
  return sh;
}
function noticesSheet_(ss) {
  var sh = ss.getSheetByName(NOTICES_TAB);
  if (!sh) { sh = ss.insertSheet(NOTICES_TAB); sh.appendRow(['When', 'Email', 'Student ID', 'Type', 'Subject', 'Body', 'Key']); }
  return sh;
}

/** All prefs rows: [{email, studentId, prefs, row}] */
function prefsAll_(ss) {
  var sh = prefsSheet_(ss);
  var values = sh.getDataRange().getValues();
  var out = [];
  for (var r = 1; r < values.length; r++) {
    var email = String(values[r][0] || '').toLowerCase();
    if (!email) continue;
    var prefs; try { prefs = JSON.parse(values[r][2] || '{}'); } catch (e) { prefs = {}; }
    out.push({ email: email, studentId: String(values[r][1] || ''), prefs: prefs, row: r + 1 });
  }
  return out;
}
function prefsCacheKey_(email) { return 'prefs_' + APP_VERSION + '_' + String(email || '').toLowerCase(); }
/**
 * One student's notification settings.
 *
 * Cached per email. Without this, every single page load opened the private Sheet and read the whole Prefs
 * tab — several hundred milliseconds on a request that otherwise serves an assembled payload out of cache,
 * which made it the slowest thing left in a warm boot. `prefsWrite_` drops the key, so a student's own save
 * is still visible immediately; `'~'` is the stored form of "this student has never set anything".
 */
function prefsRead_(email) {
  var id = getDataSheetId_(); if (!id) return null;
  var cache = CacheService.getScriptCache(), key = prefsCacheKey_(email);
  var got = cache.get(key);
  if (got) return got === '~' ? null : JSON.parse(got);
  var hit = prefsAll_(SpreadsheetApp.openById(id)).filter(function (p) { return p.email === email; })[0];
  var prefs = hit ? hit.prefs : null;
  cache.put(key, prefs ? JSON.stringify(prefs) : '~', PREFS_CACHE_TTL_SECS);
  return prefs;
}
function prefsWrite_(email, studentId, prefs) {
  var id = getDataSheetId_(); if (!id) throw new Error('Notifications need the data sheet (Phase 2) set up first.');
  var lock = LockService.getScriptLock(); lock.waitLock(10000);
  try {
    var ss = SpreadsheetApp.openById(id);
    var sh = prefsSheet_(ss);
    var all = prefsAll_(ss);
    var hit = all.filter(function (p) { return p.email === email; })[0];
    var rowVals = [email, studentId, JSON.stringify(prefs), prefs.updated];
    if (hit) sh.getRange(hit.row, 1, 1, 4).setValues([rowVals]); else sh.appendRow(rowVals);
  } finally { lock.releaseLock(); }
  try { CacheService.getScriptCache().remove(prefsCacheKey_(email)); } catch (e) {}
}

/** Append one notice and trim that student's history. */
function noticeAppend_(ss, email, studentId, type, subject, body, key) {
  var sh = noticesSheet_(ss);
  sh.appendRow([Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd'T'HH:mm:ss"), email, studentId, type, subject, body, key || '']);
  var values = sh.getDataRange().getValues();
  var mine = [];
  for (var r = 1; r < values.length; r++) if (String(values[r][1]).toLowerCase() === email) mine.push(r + 1);
  var extra = mine.length - NOTICES_KEEP_PER_STUDENT;
  for (var i = 0; i < extra; i++) sh.deleteRow(mine[i] - i);
}
/** Notices for one email, newest first. */
function noticesFor_(email, limit) {
  var id = getDataSheetId_(); if (!id) return [];
  var sh = SpreadsheetApp.openById(id).getSheetByName(NOTICES_TAB);
  if (!sh) return [];
  var values = sh.getDataRange().getValues();
  var out = [];
  for (var r = values.length - 1; r >= 1 && out.length < (limit || 30); r--) {
    if (String(values[r][1]).toLowerCase() !== email) continue;
    out.push({ when: Sched.cellToString(values[r][0]), type: String(values[r][3]), subject: String(values[r][4]), body: String(values[r][5]), key: String(values[r][6]) });
  }
  return out;
}
function noticeKeys_(ss, email) {
  var sh = ss.getSheetByName(NOTICES_TAB); if (!sh) return {};
  var values = sh.getDataRange().getValues(), out = {};
  for (var r = 1; r < values.length; r++) if (String(values[r][1]).toLowerCase() === email && values[r][6]) out[String(values[r][6])] = true;
  return out;
}
function noticesTodayCount_(ss, email, type, today) {
  var sh = ss.getSheetByName(NOTICES_TAB); if (!sh) return 0;
  var values = sh.getDataRange().getValues(), n = 0;
  for (var r = 1; r < values.length; r++) if (String(values[r][1]).toLowerCase() === email && String(values[r][3]) === type && Sched.cellToString(values[r][0]).slice(0, 10) === today) n++;
  return n;
}

/* ---------------------------------------------------------------- sending ---- */

function sendNotice_(ss, email, studentId, type, subject, textBody, key) {
  MailApp.sendEmail({ to: email, subject: subject, body: textBody + '\n\n— ' + APP_NAME + '\n' + withAccountChooser_(appUrl_()) + '\nChange or turn off these emails under More → Notifications.', name: APP_NAME });
  noticeAppend_(ss, email, studentId, type, subject, textBody, key);
}

function fmtDay_(iso) {
  var d = new Date(iso + 'T00:00:00Z');
  return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][d.getUTCDay()] + ' ' + Number(iso.slice(5, 7)) + '/' + Number(iso.slice(8, 10));
}
function itemLine_(it) {
  return '• [' + (it.short || it.className) + '] ' + it.title + (it.points ? ' (' + it.points + ' pts)' : '') + (it.dueSource === 'nextSchoolDay' ? '' : '');
}

/**
 * Called at the end of every successful sync. `changes` = diff from the previous sync (see Sync.gs).
 * Each step is independent and wrapped so one bad email can't stop the others.
 */
function notifyAfterSync_(changes) {
  var id = getDataSheetId_(); if (!id) return;
  var ss = SpreadsheetApp.openById(id);
  var subs = prefsAll_(ss).filter(function (p) { var q = p.prefs || {}; return (q.daily && q.daily.on) || (q.weekly && q.weekly.on) || (q.changes && q.changes.on) || (q.tests && q.tests.on); });
  if (!subs.length) return;
  var now = new Date();
  var today = Utilities.formatDate(now, TIMEZONE, 'yyyy-MM-dd');
  var nowMin = Number(Utilities.formatDate(now, TIMEZONE, 'H')) * 60 + Number(Utilities.formatDate(now, TIMEZONE, 'm'));
  var dow = new Date(today + 'T00:00:00Z').getUTCDay();
  // Same stored list the request path uses (computed once a day by the sync), not a fresh BellHub sweep.
  var noSchool = {};
  try {
    var m = (loadDataTabs_([]) || {}).meta || {};
    String(m.noSchoolDays || '').split(',').forEach(function (d) { if (d) noSchool[d] = 'bells'; });
    var man = noSchoolFromProperty_();
    Object.keys(man).forEach(function (d) { noSchool[d] = man[d]; });
  } catch (e) {}
  var isSchoolDay = dow >= 1 && dow <= 5 && !noSchool[today];
  var tabs = loadStagingTabs_();
  var sent = 0;

  subs.forEach(function (sub) {
    try {
      var p = sub.prefs, sid = sub.studentId;
      if (!sid) return;
      var classList = classListFor_(tabs, sid);
      var hw = homeworkPayload_({ email: sub.email, studentId: sid }, classList, today);
      if (!hw.connected) return;
      var items = hw.items;
      var focus = isSchoolDay && nowMin < (getRolloverMin_()) ? today : nextSchool_(today, noSchool);
      var byId = {}; classList.forEach(function (c) { byId[c.classId] = c; });

      // ---- change alerts (per class) ----
      if (p.changes && p.changes.on && changes && changes.length) {
        var allowed = (p.changes.classes && p.changes.classes.length) ? p.changes.classes : classList.filter(function (c) { return !c.support && !c.activity; }).map(function (c) { return String(c.classId); });
        var mine = changes.filter(function (ch) { return allowed.indexOf(String(ch.classId)) !== -1; });
        if (mine.length && noticesTodayCount_(ss, sub.email, 'changes', today) < CHANGE_ALERTS_PER_DAY) {
          var lines = mine.map(function (ch) {
            var c = byId[ch.classId] || {};
            return '• ' + (c.name || 'Class ' + ch.classId) + ': ' + (ch.action === 'new' ? 'new ' : 'updated ') + ch.kind + (ch.when ? ' for ' + fmtDay_(ch.when) : '') + (ch.text ? ' — ' + ch.text : '');
          });
          var subj = mine.length === 1 ? ((byId[mine[0].classId] || {}).name || 'A class') + ': ' + (mine[0].action === 'new' ? 'new ' : 'updated ') + mine[0].kind : mine.length + ' homework updates';
          sendNotice_(ss, sub.email, sid, 'changes', subj, lines.join('\n'), 'chg:' + today + ':' + Utilities.formatDate(now, TIMEZONE, 'HHmm'));
          sent++;
        }
      }

      // ---- daily digest ----
      if (p.daily && p.daily.on && p.lastDaily !== today && nowMin >= Sched.timeToMin(p.daily.time) && (!p.daily.schoolDaysOnly || isSchoolDay || dow === 0)) {
        var tonight = items.filter(function (it) { return it.dueOn === focus; });
        var soon = items.filter(function (it) { return it.dueOn > focus && it.dueOn <= Due.addDays(focus, 7) && TEST_RE_SERVER.test(it.title); });
        var body = 'Due ' + fmtDay_(focus) + ':\n' + (tonight.length ? tonight.map(itemLine_).join('\n') : '• Nothing due.') +
          (soon.length ? '\n\nTests & quizzes in the next week:\n' + soon.map(function (it) { return itemLine_(it) + ' — ' + fmtDay_(it.dueOn); }).join('\n') : '');
        sendNotice_(ss, sub.email, sid, 'daily', 'Due ' + fmtDay_(focus) + ': ' + tonight.length + ' item' + (tonight.length === 1 ? '' : 's'), body, 'daily:' + today);
        p.lastDaily = today; prefsWrite_(sub.email, sid, p); sent++;
      }

      // ---- weekly preview ----
      if (p.weekly && p.weekly.on && p.lastWeekly !== today && dow === Number(p.weekly.day) && nowMin >= Sched.timeToMin(p.weekly.time)) {
        var end = Due.addDays(today, 7);
        var week = items.filter(function (it) { return it.dueOn > today && it.dueOn <= end; });
        var byDay = {}; week.forEach(function (it) { (byDay[it.dueOn] = byDay[it.dueOn] || []).push(it); });
        var wbody = Object.keys(byDay).sort().map(function (d) { return fmtDay_(d) + ':\n' + byDay[d].map(itemLine_).join('\n'); }).join('\n\n') || '• Nothing due in the next 7 days.';
        sendNotice_(ss, sub.email, sid, 'weekly', 'Your week ahead: ' + week.length + ' item' + (week.length === 1 ? '' : 's'), wbody, 'weekly:' + today);
        p.lastWeekly = today; prefsWrite_(sub.email, sid, p); sent++;
      }

      // ---- test / quiz reminders (once per item) ----
      if (p.tests && p.tests.on) {
        var target = Due.addDays(today, Number(p.tests.daysBefore));
        var due = items.filter(function (it) { return it.dueOn === target && TEST_RE_SERVER.test(it.title); });
        if (due.length) {
          var keys = noticeKeys_(ss, sub.email);
          var fresh = due.filter(function (it) { return !keys['test:' + it.key]; });
          if (fresh.length) {
            var tb = fresh.map(function (it) { return itemLine_(it) + ' — ' + fmtDay_(it.dueOn); }).join('\n');
            sendNotice_(ss, sub.email, sid, 'tests', (fresh.length === 1 ? (fresh[0].short || fresh[0].className) + ' ' + fresh[0].title : fresh.length + ' tests/quizzes') + ' in ' + p.tests.daysBefore + ' day' + (Number(p.tests.daysBefore) === 1 ? '' : 's'), tb, 'test:' + fresh[0].key);
            fresh.slice(1).forEach(function (it) { noticeAppend_(ss, sub.email, sid, 'tests', '(bundled)', '', 'test:' + it.key); });
            sent++;
          }
        }
      }
    } catch (e) { Logger.log('notify %s failed: %s', sub.email, e.message); }
  });
  Logger.log('notify: %s subscriber(s), %s email(s) sent', subs.length, sent);
}

function nextSchool_(iso, noSchool) {
  var d = Due.addDays(iso, 1), g = 0;
  while (g++ < 30) { var w = new Date(d + 'T00:00:00Z').getUTCDay(); if (w >= 1 && w <= 5 && !noSchool[d]) return d; d = Due.addDays(d, 1); }
  return d;
}

/* ---------------------------------------------------------------- change detection (called from Sync.gs) ---- */

/**
 * Diff previous vs new homework/assignment rows. Only rows dated today or later matter. Returns
 * [{classId, kind:'homework'|'assignment', action:'new'|'changed', when, text}]. Empty when there was no
 * previous data (first run) so the first sync never floods anyone.
 */
function diffForNotify_(prevHw, newHwRows, prevAs, newAsRows, today) {
  var out = [];
  var trunc = function (s) { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > 140 ? s.slice(0, 140) + '…' : s; };
  if (prevHw.length) {
    var ph = {}; prevHw.forEach(function (r) { ph[r['Class ID'] + '|' + r['Plan Date']] = r; });
    newHwRows.forEach(function (row) { // [classId, planDate, homework, html, modified, autoNum]
      if (row[1] < today) return;
      var k = row[0] + '|' + row[1], old = ph[k];
      if (!old) { if (String(row[2]).trim()) out.push({ classId: row[0], kind: 'homework', action: 'new', when: row[1], text: trunc(row[2]) }); }
      else if (String(old['Homework'] || '') !== String(row[2] || '')) out.push({ classId: row[0], kind: 'homework', action: 'changed', when: row[1], text: trunc(row[2]) });
    });
  }
  if (prevAs.length) {
    var pa = {}; prevAs.forEach(function (r) { pa[r['Assignment ID']] = r; });
    newAsRows.forEach(function (row) { // [id, classId, catId, title, desc, assigned, due, max, weight]
      if (row[6] && row[6] < today) return;
      var old = pa[row[0]];
      if (!old) out.push({ classId: row[1], kind: 'assignment', action: 'new', when: row[6], text: trunc(row[3] || row[4]) + (row[7] ? ' (' + row[7] + ' pts)' : '') });
      else if (old['Title'] !== row[3] || old['Date Due'] !== row[6] || String(old['Max Points']) !== String(row[7])) out.push({ classId: row[1], kind: 'assignment', action: 'changed', when: row[6], text: trunc(row[3]) + (old['Date Due'] !== row[6] ? ' — due date ' + fmtDay_(old['Date Due']) + ' → ' + fmtDay_(row[6]) : '') });
    });
  }
  return out;
}

/* ---------------------------------------------------------------- endpoints (self-only via caller_) ---- */

function prefsApi(asId) {
  var who = caller_(asId);
  var p = prefsRead_(who.email) || defaultPrefs_();
  return { prefs: p, timeChoices: TIME_CHOICES, daysBeforeChoices: DAYS_BEFORE_CHOICES, readOnly: !!who.viewingAs };
}
function savePrefsApi(asId, raw) {
  var who = caller_(asId);
  if (who.viewingAs) throw new Error('Admin view is read-only for a student\'s settings.');
  var tabs = loadStagingTabs_();
  var ids = Sched.studentClasses(tabs, who.studentId).map(function (c) { return String(c.classId); });
  var prev = prefsRead_(who.email);
  var p = cleanPrefs_(raw, ids, prev);
  prefsWrite_(who.email, who.studentId, p);
  return { ok: true, prefs: p };
}
function inboxApi(asId) {
  var who = caller_(asId);
  return { notices: noticesFor_(who.email, 30) };
}

/** Send yourself a sample daily digest for GATE0_TEST_EMAIL's student, to the ADMIN_EMAILS — in Notify.gs, editor Run menu. */
function RUN_notifySample() {
  requireOperator_();
  var to = getAdminEmails_(); if (!to.length) { Logger.log('Set ADMIN_EMAILS first.'); return; }
  var email = String(props_().getProperty(PROP_GATE0_TEST_EMAIL) || '').toLowerCase();
  var sid = directoryLookup_(email).factsId;
  var tabs = loadStagingTabs_();
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var hw = homeworkPayload_({ email: email, studentId: sid }, classListFor_(tabs, sid), today);
  var focus = nextSchool_(today, hw.noSchool || {});
  var tonight = hw.items.filter(function (it) { return it.dueOn === focus; });
  var body = 'SAMPLE for ' + email + '\n\nDue ' + fmtDay_(focus) + ':\n' + (tonight.length ? tonight.map(itemLine_).join('\n') : '• Nothing due.');
  MailApp.sendEmail({ to: to.join(','), subject: '[' + APP_NAME + '] sample daily digest', body: body, name: APP_NAME });
  Logger.log('sent sample to %s:\n%s', to.join(','), body);
}

/* ===== Data.gs ===== */
/**
 * Data.gs — read-side loaders. Two sources, both cached in CacheService (chunked: values cap at 100KB).
 *
 *   1. The staging Sheet (schedules, periods, provisioning, attendance) — owned by facts-api-sync,
 *      opened READ-ONLY, cached 6h under a key that embeds the file's mtime so the nightly sync
 *      invalidates it on the next request. Copied from FACTS Finder (loadSearchTabsCached_).
 *   2. The private data Sheet (homework, assignments, grades, meta) — written by Sync.gs every 30 min,
 *      cached 5 min under a key that embeds the file's mtime so a fresh sync shows up immediately.
 *
 * BUMP APP_VERSION whenever a cached payload's SHAPE changes, or correct code serves stale data.
 */

/* Both cache keys embed the source file's last-modified time, so a long TTL cannot serve stale data: the key
   itself changes the moment a sync writes. A short TTL only forces needless rebuilds — the data cache was on
   5 minutes, which made some unlucky student re-read ~3,900 rows out of Sheets every 5 minutes. */
var TABS_CACHE_TTL_SECS = 21600;
var DATA_CACHE_TTL_SECS = 21600;

/** CacheService caps values at 100KB — store big JSON as <key> = chunk count + <key>_i parts. */
function cachePutChunked_(cache, key, str, ttlSecs) {
  var SIZE = 90000;
  var n = Math.ceil(str.length / SIZE) || 1;
  var payload = {};
  payload[key] = String(n);
  for (var i = 0; i < n; i++) payload[key + '_' + i] = str.substr(i * SIZE, SIZE);
  cache.putAll(payload, ttlSecs);
}
function cacheGetChunked_(cache, key) {
  var n = Number(cache.get(key));
  if (!n) return null;
  var keys = [];
  for (var i = 0; i < n; i++) keys.push(key + '_' + i);
  var got = cache.getAll(keys); // ONE round trip, not one per chunk (a 2 MB payload is ~23 chunks)
  var parts = [];
  for (var j = 0; j < n; j++) {
    var p = got[keys[j]];
    if (p === null || p === undefined) return null; // a chunk expired — treat as a full miss
    parts.push(p);
  }
  return parts.join('');
}
function cacheDropChunked_(cache, key) {
  var n = Number(cache.get(key)) || 0;
  var keys = [key];
  for (var i = 0; i < n; i++) keys.push(key + '_' + i);
  cache.removeAll(keys);
}

/** Every cell stringified (Dates → 'YYYY-MM-DD' / 'HH:MM:SS') so it survives CacheService + google.script.run. */
function serializeTabs_(tabs) {
  return (tabs || []).map(function (t) {
    return { name: t.name, values: (t.values || []).map(function (row) { return row.map(Sched.cellToString); }) };
  });
}

/* ---------------------------------------------------------------- staging Sheet ---- */

/* ---------------------------------------------------------------- source versions ----
   Both cache families key off a version string. Getting that string must itself be cheap: asking Drive for a
   file's modified time is a network round trip, and doing two of them on every page load was pure latency. */

/** Staging version — a Drive timestamp, but looked up at most once every 15 min (it changes nightly). */
function stagingVersion_() {
  var cache = CacheService.getScriptCache();
  var k = 'stgv_' + APP_VERSION;
  var v = cache.get(k);
  if (v) return v;
  var stamp = '0';
  try { stamp = String(DriveApp.getFileById(getStagingSheetId_()).getLastUpdated().getTime()); } catch (e) {}
  cache.put(k, stamp, STAGING_VERSION_TTL);
  return stamp;
}

/** Data version — a content fingerprint the sync writes. No Drive call, and unchanged data keeps caches warm. */
function dataVersion_() { return props_().getProperty(PROP_DATA_VERSION) || '0'; }

function stagingCacheKey_() { return 'stg_' + APP_VERSION + '_' + stagingVersion_(); }

/**
 * Fingerprint of the staging COLUMNS THIS APP ACTUALLY READS — the key for anything assembled from them.
 *
 * `stagingVersion_` is the whole FILE's modified time, and facts-api-sync rewrites `Attendance Today` in that
 * same file every 5-15 minutes all school day. Keying assembled per-student payloads on it meant every
 * student's payload was discarded roughly every 15 minutes because another app touched a tab this boot path
 * does not even read (attendance has its own cache entry). That silently undid most of the payload cache.
 *
 * So the file's timestamp still decides when to RE-READ the sheet — that part was right — but a re-read that
 * produces identical projected content leaves this fingerprint alone, and every warm payload survives.
 *
 * Updated only when `loadStagingTabs_` actually re-reads, so a schedule change takes effect on the next
 * re-read rather than instantly. `warmCaches_` re-reads on every sync, which bounds that at 30 minutes —
 * the refresh cadence this project already promises.
 */
function stagingContentVersion_() { return props_().getProperty(PROP_STAGING_CONTENT_VERSION) || '0'; }

/** Keep only the named columns (and optionally one row per key), preserving the header row. */
function projectTab_(values, keep, dedupeBy) {
  if (!keep || !values.length) return values;
  var header = values[0].map(function (h) { return Sched.cellToString(h).trim(); });
  var cols = keep.map(function (name) { return header.indexOf(name); }).filter(function (i) { return i !== -1; });
  /* None of the wanted headers exists: return the header row only, never every column (release review
     2026-10-08). The old fallback cached whole tabs — guardian contacts, or memo text — whenever a source
     renamed its headers. An empty result is loud on screen; a silent over-share is not. */
  if (!cols.length) { Logger.log('projectTab_: none of %s found — returning no rows', JSON.stringify(keep)); return [values[0]]; }
  var dedupeCol = dedupeBy ? header.indexOf(dedupeBy) : -1;
  var out = [cols.map(function (i) { return header[i]; })];
  var seen = {};
  for (var r = 1; r < values.length; r++) {
    if (dedupeCol !== -1) {
      var k = Sched.cellToString(values[r][dedupeCol]).trim();
      if (!k || seen[k]) continue;
      seen[k] = 1;
    }
    out.push(cols.map(function (i) { return values[r][i]; }));
  }
  return out;
}

/** The staging tabs this app uses — projected to the needed columns, serialized, cached. */
function loadStagingTabs_() {
  var cache = CacheService.getScriptCache();
  var key = stagingCacheKey_();
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);
  var ss = SpreadsheetApp.openById(getStagingSheetId_());
  var tabs = [];
  STAGING_TABS.forEach(function (spec) {
    var sh = ss.getSheetByName(spec.name);
    if (sh) tabs.push({ name: spec.name, values: projectTab_(sh.getDataRange().getValues(), spec.keep, spec.dedupeBy) });
  });
  var ser = serializeTabs_(tabs);
  var json = JSON.stringify(ser);
  /* Fingerprint the PROJECTED content, not the file. An attendance-only write changes the file's timestamp
     and lands us here, but produces byte-identical projected tabs — so the fingerprint is unchanged and every
     assembled per-student payload stays valid. Only a real schedule/staff/roster change moves it. */
  try {
    var digest = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, json);
    var hex = digest.map(function (b) { return ((b < 0 ? b + 256 : b) + 0x100).toString(16).slice(1); }).join('').slice(0, 16);
    if (props_().getProperty(PROP_STAGING_CONTENT_VERSION) !== hex) {
      props_().setProperty(PROP_STAGING_CONTENT_VERSION, hex);
      Logger.log('staging content changed -> %s (assembled payloads retired)', hex);
    }
  } catch (e) {
    // Never block a page load on the fingerprint; falling back to the timestamp is correct, just less efficient.
    Logger.log('staging fingerprint failed, falling back to the file timestamp: %s', e);
    props_().setProperty(PROP_STAGING_CONTENT_VERSION, stagingVersion_());
  }
  cachePutChunked_(cache, key, json, TABS_CACHE_TTL_SECS);
  return ser;
}

/**
 * Today's attendance exceptions for the WHOLE school, from the staging Sheet — callers filter to one student.
 *
 * Its own cache entry, 5 minutes, date-keyed: facts-api-sync rewrites this tab all day, while the tabs in
 * loadStagingTabs_ are written once at 3am and cached for hours. Keeping them apart means attendance stays
 * fresh without dragging ~9,400 rows of schedules through a re-parse every few minutes.
 *
 * The tab is EXCEPTION-ONLY — a student with no row was present. It is also legitimately missing (before the
 * first pull of the day) or header-only (a day with nobody absent), and neither is an error.
 *
 * @return {?Array<Object>} rows as objects, or null when the tab is not there at all.
 */
function loadAttendanceToday_() {
  var cache = CacheService.getScriptCache();
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var key = 'atttoday_' + APP_VERSION + '_' + today;
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);
  var rows;
  try {
    var sh = SpreadsheetApp.openById(getStagingSheetId_()).getSheetByName(ATTENDANCE_TODAY_TAB);
    if (!sh) return null;
    rows = objectsFromValues_(projectTab_(sh.getDataRange().getValues(), ATTENDANCE_TODAY_KEEP, ''));
  } catch (e) {
    Logger.log('Attendance Today unavailable: %s', e);
    return null;   // never cached: a Drive hiccup must not harden into "nobody was absent"
  }
  cachePutChunked_(cache, key, JSON.stringify(rows), ATTENDANCE_TODAY_TTL_SECS);
  return rows;
}

/**
 * The memo-check `Chapel` tab (another project's sheet, read-only), projected to the columns the card may use.
 * Cached 1 h. A failed read returns null and is NOT cached — the card then shows nothing, never a wrong week.
 */
function loadChapelRows_() { return loadMemoTab_(CHAPEL_TAB, CHAPEL_KEEP); }
/** Phase 3: spirit / exam-day / picture-day lines (MemoNotes tab). Same sheet, same projection rule. */
function loadMemoNotes_() { return loadMemoTab_(MEMO_NOTES_TAB, MEMO_NOTES_KEEP); }

function loadMemoTab_(tabName, keep) {
  var id = props_().getProperty(PROP_MEMO_SHEET_ID) || '';
  if (!id) return null;
  var cache = CacheService.getScriptCache();
  // Keyed on the sheet id too, so pointing MEMO_CHECK_SHEET_ID elsewhere takes effect at once.
  var key = 'memotab_' + APP_VERSION + '_' + id.slice(-10) + '_' + tabName;
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);   // may be the cached 'null' below
  var rows = null;
  try {
    var sh = SpreadsheetApp.openById(id).getSheetByName(tabName);
    var values = sh ? sh.getDataRange().getValues() : [];
    var header = values.length ? values[0].map(function (h) { return String(h).trim(); }) : [];
    var missing = keep.filter(function (k) { return header.indexOf(k) === -1; });
    // Every expected column must be there; otherwise refuse the tab rather than guess at a changed layout.
    if (!sh) Logger.log('%s tab not found in the memo-check sheet', tabName);
    else if (missing.length) Logger.log('%s tab is missing columns %s — not loaded', tabName, missing.join(', '));
    else rows = objectsFromValues_(projectTab_(values, keep, ''));
  } catch (e) {
    Logger.log('%s tab unavailable: %s', tabName, e);
  }
  /* A failure is cached for 10 minutes. Uncached, every page load re-opened the sheet (0.5-1.5 s) for as long as
     the tab was missing or access was lost (release review 2026-10-08). The card shows nothing meanwhile. */
  cachePutChunked_(cache, key, JSON.stringify(rows), rows === null ? 600 : CHAPEL_TTL_SECS);
  return rows;
}

/** [header,...rows] → array of objects keyed by header name. */
function objectsFromValues_(values) {
  if (!values || !values.length) return [];
  var header = values[0].map(function (h) { return Sched.cellToString(h).trim(); });
  var out = [];
  for (var r = 1; r < values.length; r++) {
    var o = {};
    for (var c = 0; c < header.length; c++) o[header[c]] = Sched.cellToString(values[r][c]);
    out.push(o);
  }
  return out;
}

/* ---------------------------------------------------------------- private data Sheet ---- */

function dataCacheKey_(tab) { return 'dat_' + APP_VERSION + '_' + tab + '_' + dataVersion_(); }

/** One data tab, cached on its own so a caller only parses what it needs. */
function dataTab_(ss, tabName) {
  var cache = CacheService.getScriptCache();
  var key = dataCacheKey_(tabName);
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);
  var rows = sheetObjects_(ss.getSheetByName(tabName));
  cachePutChunked_(cache, key, JSON.stringify(rows), DATA_CACHE_TTL_SECS);
  return rows;
}

/**
 * ONE student's grade rows, cached on their own key.
 *
 * The Grades table is the whole school's — 15,457 rows by 2026-09-23 and growing fast (it was 1,014 twelve
 * days earlier). Parsing all of it to find one student's couple of dozen rows was ~550 ms of the ~700 ms the
 * data tabs cost, on every build. This keeps that parse to once per grade change instead of once per student.
 *
 * It is NOT optional data: the Homework tab's "Ungraded" bucket is DEFINED as assignments with no score, so
 * dropping grades from the build would silently list every assignment as ungraded.
 *
 * Keyed on the grades fingerprint, not the data version, so a teacher editing one homework line does not
 * retire every student's slice.
 *
 * @return {Array<Object>} that student's rows, possibly empty.
 */
function gradesForStudent_(sid) {
  sid = String(sid || '');
  if (!sid) return [];
  var cache = CacheService.getScriptCache();
  var key = 'gstu_' + APP_VERSION + '_' + (props_().getProperty(PROP_GRADES_VERSION) || '0') + '_' + sid;
  var hit = cacheGetChunked_(cache, key);
  if (hit) return JSON.parse(hit);
  var id = getDataSheetId_();
  if (!id) return [];
  var all = dataTab_(SpreadsheetApp.openById(id), DATA_TABS.grades);
  var mine = all.filter(function (r) { return String(r['Student ID']) === sid; });
  cachePutChunked_(cache, key, JSON.stringify(mine), DATA_CACHE_TTL_SECS);
  return mine;
}

/**
 * Data tabs as arrays of objects keyed by header name; null when Phase 2 is not set up yet.
 *
 * `want` names the tabs to load — they are cached SEPARATELY, so the common page load no longer parses the
 * 1,664-row averages table it never looks at. UserState is never part of this (it changes on every tap).
 * @param {Array<string>=} want default ['homework','assignments','grades'] + meta, which is what Homework needs.
 */
function loadDataTabs_(want) {
  var id = getDataSheetId_();
  if (!id) return null;
  want = want || ['homework', 'assignments', 'grades'];
  var ss = SpreadsheetApp.openById(id);
  var out = { homework: [], assignments: [], grades: [], averages: [], attendance: [], meta: {} };
  want.forEach(function (k) { if (DATA_TABS[k]) out[k] = dataTab_(ss, DATA_TABS[k]); });
  dataTab_(ss, DATA_TABS.meta).forEach(function (r) { out.meta[r['Key']] = r['Value']; });
  return out;
}

/** A sheet as [{Header: value}], every value a string. [] for a missing/empty sheet. */
function sheetObjects_(sh) {
  if (!sh) return [];
  var values = sh.getDataRange().getValues();
  if (values.length < 2) return [];
  var headers = values[0].map(function (h) { return Sched.cellToString(h).trim(); });
  var rows = [];
  for (var r = 1; r < values.length; r++) {
    var o = {}, any = false;
    for (var c = 0; c < headers.length; c++) {
      if (!headers[c]) continue;
      var v = Sched.cellToString(values[r][c]);
      if (v !== '') any = true;
      o[headers[c]] = v;
    }
    if (any) rows.push(o);
  }
  return rows;
}

/* ---------------------------------------------------------------- per-student state ---- */
/* Done/hidden items. Keyed by the ACTIVE user's email in the private Sheet's UserState tab.
   NEVER PropertiesService.getUserProperties(): the web app runs as itscripts@, so the user store is ONE
   shared bucket and every student would see everyone else's state. */

/** @return {Object} itemKey -> state ('done') for one email. */
function userStateRead_(email) {
  var id = getDataSheetId_();
  if (!id || !email) return {};
  var sh = SpreadsheetApp.openById(id).getSheetByName(DATA_TABS.userState);
  if (!sh) return {};
  var values = sh.getDataRange().getValues();
  var out = {};
  for (var r = 1; r < values.length; r++) {
    if (String(values[r][0]).toLowerCase() !== email) continue;
    var k = String(values[r][1]), st = String(values[r][2]);
    if (st) out[k] = st; else delete out[k];
  }
  return out;
}

/** Upsert one (email, itemKey) row. state '' clears it. */
function userStateWrite_(email, itemKey, state) {
  var id = getDataSheetId_();
  if (!id || !email || !itemKey) return false;
  var lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    var ss = SpreadsheetApp.openById(id);
    var sh = ss.getSheetByName(DATA_TABS.userState) || ss.insertSheet(DATA_TABS.userState);
    if (sh.getLastRow() === 0) sh.appendRow(['Email', 'Item Key', 'State', 'Updated']);
    var values = sh.getDataRange().getValues();
    var stamp = Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd HH:mm:ss");
    for (var r = 1; r < values.length; r++) {
      if (String(values[r][0]).toLowerCase() === email && String(values[r][1]) === itemKey) {
        sh.getRange(r + 1, 3, 1, 2).setValues([[state, stamp]]);
        return true;
      }
    }
    sh.appendRow([email, itemKey, state, stamp]);
    return true;
  } finally {
    lock.releaseLock();
  }
}

/* ---------------------------------------------------------------- timing ----
   "It feels sluggish" is not something to fix by guessing. Every request records how long it took, in one
   small rolling cache entry, so RUN_showPerf can say which stage is actually slow on real phones and whether
   the caches are being hit. Two cheap cache ops; never allowed to break a request. */
function perfNote_(stage, ms) {
  try {
    var cache = CacheService.getScriptCache();
    var raw = cache.get('perf_' + APP_VERSION);
    var p = raw ? JSON.parse(raw) : {};
    var s = p[stage] || { n: 0, total: 0, max: 0 };
    s.n++; s.total += ms; if (ms > s.max) s.max = ms;
    p[stage] = s;
    cache.put('perf_' + APP_VERSION, JSON.stringify(p), 21600);
  } catch (e) { /* telemetry must never cost a page load */ }
}

/** What is actually slow, measured — in Data.gs, editor Run menu. */
function RUN_showPerf() {
  requireOperator_();
  var raw = CacheService.getScriptCache().get('perf_' + APP_VERSION);
  if (!raw) { Logger.log('No timings recorded yet (they reset when APP_VERSION changes or after 6 h).'); return; }
  var p = JSON.parse(raw);
  Logger.log('stage                 calls    avg ms    worst ms');
  Object.keys(p).sort().forEach(function (k) {
    var s = p[k];
    Logger.log('%s %s %s %s', (k + '                    ').slice(0, 20), String(s.n).padStart(6), String(Math.round(s.total / s.n)).padStart(9), String(s.max).padStart(11));
  });
  var b = p['boot-built'], c = p['boot-cached'];
  if (b && c) Logger.log('Cache hit rate on page loads: %s%% (%s cached vs %s built)', Math.round(100 * c.n / (b.n + c.n)), c.n, b.n);
  else if (b && !c) Logger.log('!! No cached page loads at all — something is invalidating the per-student cache every time.');
}

/**
 * Break the per-student build into its phases — in Data.gs, editor Run menu.
 *
 * "assemble is 5.3 s" is not actionable; which PHASE of the assemble is 5.3 s is. Two passes are timed: the
 * first takes the caches as it finds them, the second with everything warm. The gap between them is what the
 * first student after a release or a sync pays and nobody else does. Read-only — it builds payloads and throws
 * them away, and never clears a cache a live student is using.
 */
function RUN_perfTest() {
  requireOperator_();
  var email = String(props_().getProperty(PROP_GATE0_TEST_EMAIL) || '').toLowerCase();
  var sid = email ? directoryLookup_(email).factsId : '';
  if (!sid) { Logger.log('Set GATE0_TEST_EMAIL first.'); return; }
  var ctx = schedCtx_('');
  var who = { studentId: sid, email: email, fullName: '', isAdmin: false, viewingAs: '' };
  function t(fn) { var s = Date.now(); var r = fn(); return { ms: Date.now() - s, r: r }; }

  // Price the BellHub call itself, deliberately outside its cache. This is what a cold week costs ×5.
  var bellRaw = t(function () { try { return BellHub.getLobbyForDate(ctx.date); } catch (e) { return String(e); } });

  function pass(label) {
    var m = {}, x;
    x = t(function () { return loadStagingTabs_(); }); m.staging = x.ms; var tabs = x.r;
    x = t(function () { return Sched.studentClasses(tabs, sid); }); m.studentClasses = x.ms; var classes = x.r;
    m.profile = t(function () { return Sched.studentProfile(tabs, sid, classes); }).ms;
    x = t(function () { return Sched.buildPeriodTimes(tabs); }); m.periodTimes = x.ms; var periodTimes = x.r;
    x = t(function () { return classListFor_(tabs, sid, classes); }); m.classList = x.ms; var classList = x.r;
    var academic = classes.filter(function (c) { return !c.activity; });
    var dates = weekDates_(ctx.date, ctx.dow);
    m.bellsWeek = t(function () { return bellsForDays_(dates); }).ms;   // one batched read; was 5 separate ones
    m.gradeSlice = t(function () { return gradesForStudent_(sid); }).ms; // this student's rows, not the school's
    m.annotateX5 = t(function () {
      var o = [];
      for (var i = 1; i <= 5; i++) o.push(Sched.annotateSchedule(academic, periodTimes, { dayCol: String(i), nowMin: -1, quarter: ctx.quarter, bells: {} }));
      return o;
    }).ms;
    // EXACTLY what the build loads. An earlier version of this line still asked for 'grades', which the build
    // stopped loading — so it reported a cost nothing was paying and hid whether the change had worked.
    x = t(function () { return loadDataTabs_(['homework', 'assignments']); }); m.dataTabs = x.ms; var data = x.r;
    m.dataTabsPlusGrades = t(function () { return loadDataTabs_(['homework', 'assignments', 'grades']); }).ms;
    m.dueEngine = t(function () { return homeworkPayload_(who, classList, ctx.date, data); }).ms;
    m.averagesTab = t(function () { return loadDataTabs_(['averages']); }).ms;
    /* Three runs, because a single one is not trustworthy here: across passes these figures move 30-60% on
       identical work (staging read 138 / 162 / 257 ms for the same cached bytes). The MINIMUM is the honest
       estimate of the real cost; the spread tells you how much to believe any single number. */
    var runs = [t(function () { return buildBootPayload_(who, ctx); }).ms,
      t(function () { return buildBootPayload_(who, ctx); }).ms,
      t(function () { return buildBootPayload_(who, ctx); }).ms];
    m.BUILD_min = Math.min.apply(null, runs);
    m.BUILD_max = Math.max.apply(null, runs);
    m.WHOLE_BUILD = m.BUILD_min;
    Logger.log('--- %s ---', label);
    Object.keys(m).forEach(function (k) { Logger.log('   %s %s ms', (k + '                  ').slice(0, 18), m[k]); });
    return m;
  }

  var tabs0 = loadStagingTabs_();
  Logger.log('Student %s (%s). Staging rows: %s', sid, email, tabs0.map(function (x) { return x.name + '=' + (x.values.length - 1); }).join(', '));
  Logger.log('One raw BellHub.getLobbyForDate, cache bypassed: %s ms  (a cold week costs 5 of these)', bellRaw.ms);
  var a = pass('PASS 1 — caches as found');
  var b = pass('PASS 2 — fully warm (what a student actually pays)');

  /* ⚠️ Do NOT read a "cold build" number off WHOLE_BUILD in pass 1. By the time it runs, the phases above it
     have already warmed every cache it uses, so it is a warm number wearing a cold label — the first version
     of this function printed pass1-minus-pass2 as a "cold penalty" and got -158 ms, which is noise, not a
     saving. The real cold cost is in the PHASE rows of pass 1. */
  Logger.log('%s', new Array(78).join('-'));
  Logger.log('HOW TO READ THIS');
  Logger.log('  Cold vs warm, per phase (pass1 -> pass2):');
  ['staging', 'bellsWeek', 'gradeSlice', 'dataTabs', 'dataTabsPlusGrades', 'dueEngine', 'averagesTab'].forEach(function (k) {
    Logger.log('     %s %s ms -> %s ms', (k + '                  ').slice(0, 18), a[k], b[k]);
  });
  Logger.log('  Build, warm, best of three: %s ms   (worst of three %s ms — that gap is measurement noise,', b.BUILD_min, b.BUILD_max);
  Logger.log('  not work; treat any single figure above as +/- 40%%.)');
  Logger.log('  dataTabs is what the build NOW loads; dataTabsPlusGrades is what it used to — the difference');
  Logger.log('  is what per-student grade slices removed from every build.');
  Logger.log('  averagesTab is NOT in the build at all — timed only to show what deferring Grades saved.');
  Logger.log('  NOTE: this is the cost of a build, which a cached payload replaces entirely. The number that');
  Logger.log('  actually decides how the app FEELS is the cache hit rate in RUN_showPerf, from real page loads.');
}

/* ---------------------------------------------------------------- admin audit trail ---- */
/* Every time an admin opens a student's record with ?as=, a permanent row is written. These are minors'
   educational records: the Stackdriver log rotates, this does not. Written from doGet only — once per page
   open, not once per API call — and never allowed to break the page. */

/** @return {boolean} true when a row was written. */
function auditAdminView_(adminEmail, studentId, studentName, note) {
  var id = getDataSheetId_();
  if (!id || !adminEmail || !studentId) return false;
  try {
    var ss = SpreadsheetApp.openById(id);
    var sh = ss.getSheetByName(DATA_TABS.adminViews);
    if (!sh) { sh = ss.insertSheet(DATA_TABS.adminViews); sh.appendRow(['When', 'Admin', 'Student ID', 'Student', 'Note']); sh.setFrozenRows(1); }
    sh.appendRow([Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd'T'HH:mm:ss"), adminEmail, String(studentId), studentName || '', note || '']);
    var extra = sh.getLastRow() - 1 - ADMIN_VIEWS_KEEP;
    if (extra > 0) sh.deleteRows(2, extra);
    return true;
  } catch (e) {
    Logger.log('audit write failed (view still allowed): %s', e.message);
    return false;
  }
}

/** Print the recent admin views — in Data.gs, editor Run menu. */
function RUN_showAdminViews() {
  requireOperator_();
  var id = getDataSheetId_();
  var sh = id ? SpreadsheetApp.openById(id).getSheetByName(DATA_TABS.adminViews) : null;
  if (!sh || sh.getLastRow() < 2) { Logger.log('No admin views recorded.'); return; }
  var values = sh.getDataRange().getValues();
  Logger.log('%s admin view(s) recorded, most recent last:', values.length - 1);
  values.slice(Math.max(1, values.length - 50)).forEach(function (r) {
    Logger.log('  %s  %s → student %s (%s) %s', Sched.cellToString(r[0]), r[1], r[2], r[3], r[4] || '');
  });
}

/** Drop every cache so the next request rebuilds — in Data.gs, editor Run menu. */
function RUN_clearCaches() {
  requireOperator_();
  var cache = CacheService.getScriptCache();
  cache.remove('stgv_' + APP_VERSION);
  cacheDropChunked_(cache, stagingCacheKey_());
  ['homework', 'assignments', 'grades', 'averages', 'meta'].forEach(function (k) {
    if (DATA_TABS[k]) cacheDropChunked_(cache, dataCacheKey_(DATA_TABS[k]));
  });
  // Assembled per-student payloads: no way to enumerate them, so bump the salt instead — every key
  // embeds it, so one write invalidates every student's payload at once.
  props_().setProperty(PROP_BOOT_SALT, String(Date.now()));
  Logger.log('caches cleared (staging, data tabs, and every assembled student payload)');
}

/* ===== Bells.gs ===== */
/**
 * Bells.gs — bell schedule + closed days from the BellHub library (same source FACTS Finder uses).
 *
 * Two uses:
 *   1. Delay / exam / special days: BellHub's period times override the FACTS normal-day times per SLOT
 *      (bellSlotTimes_ maps "1st Period" → P1 etc.). Copied from FACTS Finder (bellForDateCached_, bellSlotTimes).
 *   2. No-school days for the due engine: a BellHub "closed" verdict can mean a real holiday OR a date nobody
 *      has entered (FACTS Finder, 2026-08-06), so closed days count ONLY when BellHub also names a source/mode
 *      for that date, and the Script Property NO_SCHOOL_DATES ("2026-09-25,2026-11-26,…") is always added.
 *      RUN_bellTest prints the raw verdict for a date so the rule can be checked against reality.
 *
 * Every BellHub call is wrapped: if the library is missing or throws, the app falls back to FACTS times and
 * weekends-only, and never breaks.
 */

var PROP_NO_SCHOOL_DATES = 'NO_SCHOOL_DATES';

function bellCacheKey_(dateStr) { return 'bell_' + APP_VERSION + '_' + dateStr; }

/** One BellHub call, no caching. MEASURED at 4,367 ms uncached — which is why nothing calls this in a loop. */
function bellFetch_(dateStr) {
  try {
    var l = BellHub.getLobbyForDate(dateStr);
    return { ok: true, date: l.date, weekday: l.weekday, mode: l.mode || '', source: l.source || '', closed: !!l.closed, periods: l.periods || [], warning: l.warning || null };
  } catch (err) {
    return { ok: false, closed: false, mode: '', source: '', periods: [], error: String(err).slice(0, 200) };
  }
}

/** BellHub verdict for one date, cached 6 h. {ok, date, weekday, mode, source, closed, periods[]} */
function bellForDateCached_(dateStr) {
  var cache = CacheService.getScriptCache();
  var key = bellCacheKey_(dateStr);
  var hit = cache.get(key);
  if (hit) return JSON.parse(hit);
  var payload = bellFetch_(dateStr);
  // 6 h, not 10 min: a given date's bell schedule effectively never changes once entered, and every miss is a
  // cross-library call sitting in a student's page load.
  cache.put(key, JSON.stringify(payload), 21600);
  return payload;
}

/**
 * A whole week's bells in ONE cache round trip.
 *
 * The build asked for five days one at a time — five separate CacheService reads, measured at 152 ms warm for
 * what is a single batched read's worth of work. getAll/putAll collapse that; only genuine misses fall through
 * to BellHub, and those are 4.4 s each, so they are worth keeping rare.
 *
 * @return {Object} iso date -> the same shape bellsForDay_ returns.
 */
function bellsForDays_(dates) {
  var cache = CacheService.getScriptCache();
  var keys = (dates || []).map(bellCacheKey_);
  var got = {};
  try { got = cache.getAll(keys) || {}; } catch (e) { got = {}; }
  var out = {}, toPut = {}, misses = 0;
  (dates || []).forEach(function (d, i) {
    var b = null;
    if (got[keys[i]]) { try { b = JSON.parse(got[keys[i]]); } catch (e) { b = null; } }
    if (!b) { b = bellFetch_(d); toPut[keys[i]] = JSON.stringify(b); misses++; }
    out[d] = bellsFromVerdict_(b);
  });
  if (misses) {
    try { cache.putAll(toPut, 21600); } catch (e) { /* a failed write just means the next request re-fetches */ }
  }
  return out;
}

/** BellHub periods → { P1: {start,end,name}, Homeroom: …, Lunch: … } keyed like FACTS slot labels. */
function bellSlotTimes_(bellPeriods) {
  var out = {};
  (bellPeriods || []).forEach(function (p) {
    var name = String((p && p.name) || '');
    if (!p || !p.start) return;
    var key = null;
    var m = /(\d+)\s*(?:st|nd|rd|th)?\s*period/i.exec(name);
    if (m) key = 'P' + Number(m[1]);
    else if (/homeroom/i.test(name)) key = 'Homeroom';
    else if (/lunch/i.test(name)) key = 'Lunch';
    else if (/chapel/i.test(name)) key = 'Chapel';
    if (key && !out[key]) out[key] = { start: p.start, end: p.end || '', name: name };
  });
  return out;
}

/** Bells keyed by slot for one date, with grade-banded FACTS labels ('P4 7-8', 'Lunch 9-12') resolved by annotateSchedule via prefix. */
/** Shared by the single-day and whole-week paths so they can never disagree. */
function bellsFromVerdict_(b) {
  var slots = b.ok ? bellSlotTimes_(b.periods) : {};
  // annotateSchedule looks up bells[slotLabel] exactly; add prefix aliases for banded labels.
  var out = {};
  Object.keys(slots).forEach(function (k) { out[k] = slots[k]; });
  return { slots: out, mode: b.mode, closed: b.closed, ok: b.ok, source: b.source };
}

function bellsForDay_(dateStr) {
  return bellsFromVerdict_(bellForDateCached_(dateStr));
}

/** Explicit no-school dates from the Script Property. */
function noSchoolFromProperty_() {
  var raw = props_().getProperty(PROP_NO_SCHOOL_DATES) || '';
  var out = {};
  raw.split(/[,\s]+/).forEach(function (d) { if (/^\d{4}-\d{2}-\d{2}$/.test(d)) out[d] = 'property'; });
  return out;
}

/**
 * The school's own Google calendar → closed dates in [fromIso, toIso] as {iso: title}.
 *
 * Read from the SOURCE, not from FACTS's copy of it (Josh, 2026-09-23): public .ics over plain HTTPS, no
 * Calendar OAuth scope, and nothing here can write to a calendar. Cached 6h.
 *
 * A failed fetch returns {} and is NOT cached — same rule as the athletics sweep. Google rate-limits these
 * URLs, and a 429 must never harden into "nothing is closed", which is the direction that silently moves
 * deadlines.
 */
/**
 * The raw school-calendar .ics, cached so EVERY consumer shares one fetch.
 *
 * Google rate-limits these public .ics URLs, and we earned a 429 on 2026-09-23 by fetching the same 595 KB
 * file twice in one run (RUN_checkNoSchool fetched it, then noSchoolDaysCached_ fetched it again). One cached
 * body, chunked because it is far over the 100 KB per-value cache limit.
 *
 * @return {?string} the .ics body, or null when it could not be read. Never returns '' for a failure — an
 *   empty calendar and an unreadable one must stay distinguishable all the way up.
 */
function schoolCalendarIcs_() {
  var cache = CacheService.getScriptCache();
  var key = 'calics_' + APP_VERSION;
  var hit = cacheGetChunked_(cache, key);
  if (hit) return hit;
  try {
    var url = ATHLETICS_ICS_URL.replace('%ID%', encodeURIComponent(SCHOOL_CALENDAR_ID));
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    if (res.getResponseCode() !== 200) {
      Logger.log('School calendar -> HTTP %s (Google rate-limits these .ics URLs; it recovers on its own)', res.getResponseCode());
      return null;   // NOT cached: a 429 must never harden into "nothing is closed"
    }
    var body = res.getContentText();
    cachePutChunked_(cache, key, body, 3600);
    return body;
  } catch (e) {
    Logger.log('School calendar unreachable (%s)', e);
    return null;
  }
}

function calendarClosedDays_(fromIso, toIso) {
  var body = schoolCalendarIcs_();
  if (body === null) {
    Logger.log('keeping BellHub only for %s..%s', fromIso, toIso);
    return null;     // null = COULD NOT CHECK. {} would mean "checked, nothing closed" — a very different thing.
  }
  return SchoolCal.classify(Ath.icsDayIndex(body, fromIso, toIso)).closed;
}

/** Early-dismissal days in [fromIso, toIso] as {iso: title} — SchoolCal's EARLY bucket, the SAME classifier the due
 *  engine uses. null = could not check (never cached as 'none'). Still school days; the card just says so. */
function calendarEarlyDays_(fromIso, toIso) {
  var body = schoolCalendarIcs_();
  if (body === null) return null;
  return SchoolCal.classify(Ath.icsDayIndex(body, fromIso, toIso)).early;
}

/**
 * School-wide inputs for the News & Info card (phase 2, 2026-10-08): closed days, early dismissals and the current
 * quarter's end, for the three weeks from `todayIso`. One bundle shared by every student, cached 6 h per date;
 * when a source could not be read the bundle is cached for 10 minutes only and that source is simply empty —
 * the card then omits those lines rather than asserting a quiet week.
 */
/* REQUEST PATH: a cache read only, never a fetch (release review 2026-10-08). The first version built the bundle on a
   page load and walked ~10 cold BellHub dates (4.4 s each) whenever its 6-hour entry expired mid-day. */
function schoolNotes_(todayIso) {
  var hit = null;
  try { hit = CacheService.getScriptCache().get(schoolNotesKey_(todayIso)); } catch (e) { hit = null; }
  if (hit) return JSON.parse(hit);
  return { calClosed: {}, early: {}, complete: false, missing: true };   // the caller still has the due engine's closed days
}
function schoolNotesKey_(todayIso) { return 'notes_' + APP_VERSION + '_' + todayIso; }

/* SYNC PATH (warmCaches_, every 30 min): the school calendar's closed and early-dismissal days for the next 14 days.
   One .ics read, cached 1 h by schoolCalendarIcs_, so a snow day the office posts reaches the card within ~90 min.
   BellHub closures are not re-walked here: the due engine's Meta list (daily) and this week's bells already have them.
   Cached 45 min, so a stopped sync lets it lapse instead of serving a stale week. */
function schoolNotesBuild_(todayIso) {
  var to = Due.addDays(todayIso, 14);
  var calClosed = {}, early = null, complete = true;
  try {
    var c = calendarClosedDays_(todayIso, to);
    if (c === null) complete = false;
    else Object.keys(c).forEach(function (d) { calClosed[d] = 'calendar:' + String(c[d]).split('  [')[0]; });
  } catch (e) { Logger.log('notes: calendar closures failed: %s', e); complete = false; }
  try { early = calendarEarlyDays_(todayIso, to); } catch (e2) { Logger.log('notes: early-dismissal read failed: %s', e2); }
  if (early === null) complete = false;
  var out = { calClosed: calClosed, early: early || {}, complete: complete };
  try { CacheService.getScriptCache().put(schoolNotesKey_(todayIso), JSON.stringify(out), complete ? 2700 : 600); } catch (e3) { /* next sync retries */ }
  return out;
}

/**
 * No-school dates in [fromIso, toIso] as {iso: reason}. Three sources, unioned, in increasing authority:
 *
 *   1. BellHub      — accurate near-term, but it is not populated months ahead.
 *   2. The school's Google calendar — the office maintains it, so it carries Thanksgiving, Christmas and MLK
 *      long before BellHub does, AND it is where a SNOW DAY appears. That last one is the real reason this is
 *      automatic rather than a list someone pastes once: an unplanned closure is exactly the case a manual
 *      list would miss, and exactly the day it matters most.
 *   3. NO_SCHOOL_DATES — Josh's manual override, always wins.
 *
 * Only the CLOSED bucket is taken. Early dismissals are still school days, and "no school for
 * non-participants" is not a closure for the students taking part; both are excluded by SchoolCal.classify
 * and surfaced by RUN_checkNoSchool for a human instead.
 *
 * Cached 6h. Called by the SYNC, not by a page load — this must never put a calendar fetch in a student's request.
 *
 * ⚠️ RETURNS `{days, complete}`, not a bare map. `complete` is false when the calendar could not be read, and
 * it matters: Google rate-limits these .ics URLs, and on 2026-09-23 a 429 during RUN_syncNow produced a
 * BellHub-only list that was then (a) cached for six hours and (b) stamped in Meta as successfully computed
 * for the day — so a transient rate-limit would have silently cost a whole day of closed days. An incomplete
 * result is now cached briefly and the caller is told not to treat it as the day's answer.
 */
function noSchoolDaysCached_(fromIso, toIso) {
  var cache = CacheService.getScriptCache();
  var key = 'nosch_' + APP_VERSION + '_' + fromIso + '_' + toIso;
  var hit = cache.get(key);
  var cached = hit ? JSON.parse(hit) : null;
  var out, complete;
  if (cached) {
    out = cached.days || {};
    complete = !!cached.complete;
  } else {
    out = {};
    var d = fromIso, guard = 0;
    while (d <= toIso && guard++ < 70) {
      var dow = new Date(d + 'T00:00:00Z').getUTCDay();
      if (dow >= 1 && dow <= 5) {
        var b = bellForDateCached_(d);
        if (b.ok && b.closed && (b.source || b.mode)) out[d] = 'bells:' + (b.mode || b.source);
      }
      d = Due.addDays(d, 1);
    }
    /* The calendar looks MUCH further ahead than BellHub does, deliberately.
       BellHub costs one cross-library call per weekday, so its window stays tight. The calendar costs nothing
       extra — the body is already fetched and cached, and widening the range only changes which rows are kept.
       It matters because teachers pre-enter future days (homework typed 2026-09-07 for 11/4-11/6 is real). A
       record with planDate 2026-11-24 needs to know 11/25 is closed to place it on 11/30, and with a +45 day
       window that closure is simply not in the list yet. It would come right before the item became visible,
       but relying on that timing is exactly the kind of subtlety that turns into a silent wrong due date. */
    var fromCal = calendarClosedDays_(fromIso, Due.addDays(toIso, 150));
    complete = fromCal !== null;
    if (complete) {
      var added = Object.keys(fromCal).filter(function (k) { return !out[k]; });
      added.forEach(function (k) { out[k] = 'calendar:' + String(fromCal[k]).split('  [')[0]; });
      if (added.length) Logger.log('school calendar added %s closed day(s) BellHub did not have: %s', added.length, added.sort().join(', '));
    }
    /* A complete answer keeps for 6 hours. An incomplete one keeps for 10 minutes — long enough not to hammer
       a URL that is already rate-limiting us, short enough that the next 30-minute sync retries. */
    cache.put(key, JSON.stringify({ days: out, complete: complete }), complete ? 21600 : 600);
  }
  var prop = noSchoolFromProperty_();
  Object.keys(prop).forEach(function (k) { out[k] = prop[k]; });
  return { days: out, complete: complete };
}

/** Print BellHub's raw verdict for a date — in Bells.gs, editor Run menu. Set DATE below. */
function RUN_bellTest() {
  requireOperator_();
  var DATE = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd'); // e.g. '2026-09-25' (a no-school Friday) or a past delay day
  var b = bellForDateCached_(DATE);
  Logger.log('BellHub %s → ok=%s closed=%s mode=%s source=%s periods=%s', DATE, b.ok, b.closed, b.mode, b.source, (b.periods || []).length);
  (b.periods || []).forEach(function (p) { Logger.log('  %s %s-%s %s', p.name, p.start, p.end, p.type || ''); });
  if (b.error) Logger.log('error: %s', b.error);
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var ns = noSchoolDaysCached_(today, Due.addDays(today, 28));
  Logger.log('no-school days next 4 weeks (complete=%s): %s', ns.complete, JSON.stringify(ns.days));
}

/**
 * Does the due engine know about every closed day the school calendar names? — in Bells.gs, editor Run menu.
 *
 * WHY THIS MATTERS MORE THAN IT LOOKS: the whole due engine rests on "due the NEXT SCHOOL DAY". If it thinks a
 * closed day is a school day, every piece of homework typed the day before is shown due on a day nobody is in
 * the building — silently, with no error anywhere. That is the worst class of bug this app can have, because
 * it looks completely normal on screen.
 *
 * Today the closed-day list comes from BellHub plus the manual NO_SCHOOL_DATES property. The school's own
 * Google calendar names them too ("School and Offices Closed", "no school for students", "Early Dismissal"),
 * so this cross-checks the two and prints the exact property value to paste if they disagree.
 *
 * DELIBERATELY NOT AUTOMATIC. Matching prose to decide a closed day is a guess, and a wrong guess here moves
 * real due dates. This proposes; Josh disposes, via RUN_setNoSchoolDates.
 * READ-ONLY — one public .ics fetch, no Calendar scope, nothing written.
 */
function RUN_checkNoSchool() {
  requireOperator_();
  var today = Utilities.formatDate(new Date(), TIMEZONE, 'yyyy-MM-dd');
  var to = Due.addDays(today, 120);

  var knownRes = noSchoolDaysCached_(today, to);       // what the engine believes right now
  var known = knownRes.days;
  var manual = noSchoolFromProperty_();
  Logger.log('Window %s .. %s', today, to);
  if (!knownRes.complete) Logger.log('!! The school calendar could not be read just now (rate limit?), so the engine list below is BellHub-only.');
  Logger.log('NO_SCHOOL_DATES property: %s', props_().getProperty(PROP_NO_SCHOOL_DATES) || '(unset)');
  Logger.log('The due engine currently treats these as closed: %s', Object.keys(known).sort().join(', ') || '(none)');
  Logger.log('%s', new Array(78).join('-'));

  // Shares the cached body with the sync — two fetches of this 595 KB file in one run is what earned a 429.
  var body = schoolCalendarIcs_();
  if (body === null) {
    Logger.log('The school calendar could not be read, so there is nothing to cross-check against.');
    Logger.log('Google rate-limits these .ics URLs and it clears on its own — wait a few minutes and re-run.');
    return;
  }

  /* The SAME classifier the live sync uses (SchoolCal.classify). Deliberately not a second copy of the rules:
     an audit that classifies differently from the thing it audits is worse than no audit.
     icsDayIndex, not parseIcs — one all-day row can be a whole break ("School and Offices Closed" 2026-12-23
     carries DTEND 2027-01-02, ten days), and parseIcs records only an event's start date. */
  var buckets = SchoolCal.classify(Ath.icsDayIndex(body, today, to));
  var closed = buckets.closed, early = buckets.early, review = buckets.review;

  Logger.log('CALENDAR SAYS CLOSED (%s):', Object.keys(closed).length);
  Object.keys(closed).sort().forEach(function (d) {
    Logger.log('   %s  %s   %s', d, known[d] ? 'engine KNOWS' : '!! ENGINE DOES NOT KNOW', closed[d].slice(0, 58));
  });
  Logger.log('CALENDAR SAYS EARLY DISMISSAL — still a school day, must NOT be in the list (%s):', Object.keys(early).length);
  Object.keys(early).sort().forEach(function (d) {
    Logger.log('   %s  %s   %s', d, known[d] ? '!! WRONGLY LISTED AS CLOSED' : 'correctly not listed', early[d].slice(0, 58));
  });
  Logger.log('NEEDS YOUR EYES — not proposed either way (%s):', Object.keys(review).length);
  Object.keys(review).sort().forEach(function (d) { Logger.log('   %s  %s', d, review[d].slice(0, 86)); });

  var missing = Object.keys(closed).filter(function (d) { return !known[d]; }).sort();
  Logger.log('%s', new Array(78).join('-'));
  if (!missing.length) {
    Logger.log('No gaps: every closed day the calendar names is already known to the due engine.');
    Logger.log('The calendar is a LIVE source now (Josh, 2026-09-23) — the daily sync unions BellHub + this');
    Logger.log('calendar + NO_SCHOOL_DATES, so a snow day the office posts is picked up on its own.');
  } else {
    /* Reaching here after the calendar became a live source means the union did not take effect — the usual
       cause is a cached no-school list from before the change, or a failed .ics fetch (which is deliberately
       never cached as "nothing closed"). Say so, rather than sending Josh to paste a list by hand. */
    Logger.log('%s closed day(s) the due engine does NOT know about: %s', missing.length, missing.join(', '));
    Logger.log('These SHOULD be picked up automatically. If this list is not empty:');
    Logger.log('  1. run RUN_clearCaches (Data.gs) — a no-school list cached before the calendar was wired in');
    Logger.log('     survives for up to 6 hours, then re-run this;');
    Logger.log('  2. if they are still missing, the .ics fetch is failing — check the log above for an HTTP code;');
    Logger.log('  3. to force them regardless, set DATES in RUN_setNoSchoolDates to exactly this and run it:');
    var merged = Object.keys(manual).concat(missing).sort().filter(function (d, i, a) { return a.indexOf(d) === i; });
    Logger.log('     %s', merged.join(','));
  }
}

/** Set explicit no-school dates — in Bells.gs, editor Run menu. Edit DATES first. Comma-separated YYYY-MM-DD. */
function RUN_setNoSchoolDates() {
  requireOperator_();
  var DATES = ''; // e.g. '2026-09-25,2026-11-25,2026-11-26,2026-11-27'
  if (!DATES) { Logger.log('Edit DATES in RUN_setNoSchoolDates first. Current: %s', props_().getProperty(PROP_NO_SCHOOL_DATES) || '(unset)'); return; }
  props_().setProperty(PROP_NO_SCHOOL_DATES, DATES);
  RUN_clearCaches();
  Logger.log('NO_SCHOOL_DATES = %s', DATES);
}

