    bootApi: bootApi,
    athleticsApi: athleticsApi,
    gradesApi: gradesApi,
    savePrefsApi: savePrefsApi,
    inboxApi: inboxApi,
    attendanceApi: attendanceApi,
    prefsApi: prefsApi,
    homeworkApi: homeworkApi,
    News: News,
    newsFor_: newsFor_,
    schoolNotes_: schoolNotes_,
    buildBootPayload_: buildBootPayload_,
    schedCtx_: schedCtx_,
    weekDates_: weekDates_,
    classListFor_: classListFor_,
    loadStagingTabs_: loadStagingTabs_,
    loadDataTabs_: loadDataTabs_,
